(window.STORIES=window.STORIES||[]).push(...[{"n": 106, "l": "الجزء 80 | الإخلاص | وقصة اصحاب الغار الجزء الأول", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثمانون\n#الإخلاص_وقصة_أصحاب_الغار_الجزء_الأول\nاتكلمنا المرة إللي فاتت عن الأحداث بعد غزوة أحد وشفنا آيات القرآن إللي نزلت وصنّفت المجتمع لمؤمنين ومنافقين وشهداء،\nخلصت غزوة أحد ورجع المسلمون لممارسة حياتهم اليومية، إللي عنده جراح محتاجة تخف، وإللي رجع لشغله في زراعة البساتين و....و...\nوطبعا المسلمون بيتقابلوا مع رسول الله ﷺ في الصلوات الخمس كل يوم،\n قلنا قبل كده إن رسول الله ﷺ كان بيربي الصحابة تربية إيمانية وكان بينوّع في طريقة تربيته لهم، مرة عن طريق القصة ومرة عن طريق مواعظ مباشرة، ومرة كان يقرأ عليهم القرآن فقط، \nرسول الله ﷺ كان عايز يعلم الصحابة معنى الإخلاص، فهيحكي لهم قصة عشان يوريهم الإخلاص ممكن يعمل إيه وبالتالي هم نفسهم هيكونوا حريصين إنهم يحققوا الإخلاص ده\n☆طيب هو رسول الله ﷺ ليه عايز يعلم الصحابة الإخلاص أصلا\nلو تفتكروا لما كنا بنتكلم عن رحلة المعراج واتكلمنا عن حوض رسول الله ﷺ ومين الناس إللي هتشرب منه، قلنا إن عشان ربنا يتقبل مننا العمل الصالح لازم نكون محققين شرطين:\nالإخلاص والمتابعة،\nالمتابعة هي اتباع رسول الله ﷺ في كل شيء واتكلمنا بالتفصيل عن النقطة دي في الجزء الرابع والثلاثين عشان لو حبيتم ترجعوا لها تاني\nربنا قال:\n\"فَمَن كَانَ يَرْجُو لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا \"\nفليعمل عملا صالحا يعني موافق للسنة، زي ما رسول الله ﷺ كان بيعمل بالضبط من غير ما يبتدع،\nوشرط المتابعة لرسول الله ﷺ يعتبر سهل لو قارناه بالشرط الأول وهو الإخلاص،\n\"وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا \"\nلأن الرياء أو خلينا نقول الشرك زي ما رسول الله ﷺ سمّاه إللي هو عكس الإخلاص أخفى من دبيب النمل،\nيعني لو حد فينا قاعد في البيت هيحس بدبة النملة \nوهي ماشية في الشقة\nطبعا لأ، محدش فينا هيعرف إن في نملة في البيت غير لما نشوفها بعنينا، تخيلوا بقى لما تبقى حاجة أخفى من دبة النملة هل ممكن إننا نحس بيها\nمستحيل طبعا\nطيب وإيه المشكلة يعني من الرياء\nالرياء سبب لحبوط العمل، وإن ربنا لا يتقبله من الإنسان،\nربنا بنفسه بيقول في الحديث القدسي:\n\" أَنَا أَغْنَى الشُّرَكَاءِ عَنِ الشِّرْكِ، مَنْ عَمِلَ عَمَلًا أَشْرَكَ فِيهِ مَعِي غَيْرِي، تَرَكْتُهُ وَشِرْكَهُ \"\nواحد بيحفظ قرآن عشان الأجر 《و》عشان يأخذ إجازة ويقول للناس أنا معايا إجازة في القرآن وبالتالي الناس تحترمه وتقدره وينظروا له نظرة إعجاب.\nواحدة بتتعلم العلم الشرعي عشان تعبد ربنا 《و》 عشان الناس تقول عليها أه فلانة العالمة وتبقى مشهورة بين الناس،\nواحد بيعمل خير عشان الأجر 《و》عشان الناس متجبش سيرته إلا بالخير ويبقى محبوب وسط الناس.\nواحدة بتتصدق عشان أجر الصدقة 《و》عشان الناس تقول عليها ده فلانة دي كريمة وبتساعد الفقراء والناس تمدحها،\nالأمثلة دي وغيرها كثير، مثال على إللي بيعمل عمل لله عشان الأجر وعشان حاجة تانية،\nوالنتيجة للأسف هتكون زي ما ربنا قال:\n\"تَرَكْتُهُ وَشِرْكَهُ\"\nيعني مفيش عمل أصلا، ربنا لم يتقبل العمل من أساسه، \nلو واحد عَمِل عَملا لله بنسبة ٩٩% لله و ١% بس لغير الله، ربنا لن يتقبل منه\n☆خلونا نقرب المعنى ونشوف مثال\nلو واحدة قالت لزوجها شوف أنا بحبك بنسبة ٩٠ % لكن ١٠ % الباقيين بحب ابن الجيران،\nهل هو هيقبل ويرضى بالتسعين ويقول أهه أحسن من ما فيش\nولّا هيقلب الدنيا كلها عشان ١٠ % دول ولن يقبل بإن زوجته تحب واحد تاني ولو بنسبة بسيطة \nأهه ولله المثل الأعلى في السماوات والأرض الوضع كده في أعمالنا الصالحة مع ربنا فهو أغنى الشركاء عن الشرك\nعشان كده رسول الله ﷺ كان حريص إنه يعلم الصحابة معنى الإخلاص وإزاي يجتهدوا عشان يحققوه\nخلونا نشوف رسول الله ﷺ حكى إيه للصحابة\nقال رسول الله ﷺ للصحابة:\nهل تعرفون قصة أصحاب الرّقِيم؟\n\" أَمْ حَسِبْتَ أَنَّ أَصْحَابَ الْكَهْفِ وَ《الرَّقِيمِ》 كَانُوا مِنْ آيَاتِنَا عَجَبًا\"\nفالصحابة قالوا :\nلا يا رسول الله\nفقال لهم رسول الله ﷺ : \nخرج ثلاثة ممّن كانوا قبلكم، يعني ثلاثة أشخاص خرجوا من بيوتهم رايحين مشوار....مسافرين....بيتمشوا ...فنزل عليهم المطر فآواهم المبيت إلى غار،\nيعني دخلوا الغار عشان يحتموا من المطر، والغار عبارة عن فتحة داخل الجبل، فقالوا نروح نقعد فيه لحد ما المطر يقف، دخلوا فعلا الغار وبعدها سقط حجر من الجبل وسد فتحة الغار،\nعارفين لما بيكون في أمطار شديدة، بتحصل انهيارات والأمطار بتحرك الصخور،\nفحصل إن الصخرة اتحركت ووقعت على باب الغار قفلته خالص، حاولوا يحركوها متحركتش\nطبعا أي حد في مكانهم هيخاف ويترعب، متخيلين ناس داخل جبل اتقفل عليهم المخرج الوحيد ومش معاهم أكل ولا مية، وحتى لو معاهم هيكفيهم كم يوم يعني\nإللي يشوف الموقف يقول إن الثلاثة دول هيهلكوا أكيد، هيموتوا موت بطيء\nوهم نفسهم كانوا عارفين الوضع الخطير إللي كانوا فيه، فقالوا : \nمحدش هينجينا من الأزمة دي غير ربنا، فخلونا ندعي ربنا بصالح أعمالنا،  \nيعني كل واحد يشوف إيه أكثر عمل صالح عمله في حياته ويتوسل إلى الله به،\n◇فقال الأول:\nيارب انت عارف إن أنا كان عندي أبوان شيخان كبيران وعندي زوجة وأطفال صغار براعيهم، \nفلما كنت برجع للبيت ومعايا اللبن بعد ما حلبته، كنت ببدأ بأبوي أخليهم يشربوا قبل أبنائي الصغار،\nومكنتش بقدّم على أبوي أي حاجة.. لا أهل ولا مال، كانوا هم عندي رقم واحد،\nوفي يوم من الأيام اتأخرت عليهم بسبب إني مكنتش لاقي زرع أخضر للغنم ففضلت ماشي...ماشي... لحد ما لقيت الزرع وأكّلت الغنم وضرعها امتلأ لبن، ورجعت باللبن عشان يشربوا فلقيتهم ناموا،\nفكرهت إني أصحيهم وأزعجهم، روحت واقف باللبن جنبهم مستنيهم يصحوا، وأولادي عند رجلي عمالين بيعيطوا من الجوع،\nفكرهت إني أسيبهم وأمشي وكرهت أني أسقي الأطفال قبل ما أسقيهم،\nوفضلنا على الوضع ده لحد ما الفجر طلع وصحيوا من النوم وشَرِبا من اللبن،\nفيارب لو كنت تعلم إني عملت كده ابتغاء مرضاتك، عشان عايز رضاك يعني،\nففرّج عنا ما نحن فيه\nفتحركت الصخرة حاجة بسيطة شافوا منها السماء، لكنهم مش هيعرفوا يخرجوا لسه.\n☆الرجل ده وصل بالبر لأعلى درجاته لأنه عمل حاجة نادر جدا إن ولد يعملها مع أبويه\nوهي إنه يقدم أبويه على أبنائه. \n◇طيب ليه دي حاجة نادرة\n لأن الابن بيحب أبويه حب تكلّف، بعكس الأب والأم طبعهم إنهم يحبوا أبناءهم، يعني ربنا طبع الأبوين إنهم يحبوا أبناءهم حب فطري،\nيعني مهما الابن عامل الأب والأم بأسلوب سيء وفضّل غيرهم عليهم فهم هيفضلوا يحبوه مهما حصل،\nلكن لو الأبوين عاملوا الأبناء معاملة سيئة هيكرهوهم، عشان كده ربنا لم يوصِ الأباء بالأبناء وبرعايتهم لكن أوصى الأبناء برعاية آباءهم\nوانتم أكيد شوفتم أمثلة كثيرة لأباء وأمهات ممكن يضحوا بكل ما يملكون عشان يعالجوا أبنائهم ومحدش فيهم يحس بالندم إنه صرف أمواله كلها،\nفي حين إننا شفنا أمثلة كثيرة لأبناء ممكن يتخلصوا من أبائهم عشان يورثوهم أو عشان خلاص زهقوا وتعبوا منهم\n《طبعا بتكلم في قاعدة عامة مليش دعوة بالناس إللي بتشذ عن القاعدة \n》\nولو لاحظتم في القرآن هنلاقي لما ربنا بينهانا عن الشرك بييجي على طول وراه وبالوالدين إحسانا،\n\"وَإِذْ أَخَذْنَا مِيثَاقَ بَنِي إِسْرَائِيلَ لَا تَعْبُدُونَ إِلَّا اللَّهَ وَبِالْوَالِدَيْنِ إِحْسَانًا.\"\n\"وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حُسْنًا\"\n\"وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ إِحْسَانًا\"\nفالرجل هنا أب وبيحب أبناؤه الصغار حب طَبعي، وكمان عمالين بيعيطوا عايزين يشربوا من اللبن، ومع ذلك مرضاش إن حد تاني يشرب قبل أبويه حتى لو كانوا أبناءه،\nلأ ويفضل كمان واقف لحد الفجر بعد اللّف بتاع طول اليوم والجري وراء الغنم ،\nطيب كان على الأقل ينام، لأن تاني يوم محتاج يخرج بالغنم فلازم يريح شوية،\nومينفعش مثلا ينام جنب الغنم وإلا الذئب هياكل الغنم أو الغنم تسرح مع نفسها وميعرفش يلمهم فلازم يبقى مصحصح لهم\nلكنه منمش وفضل واقف مستنيهم يصحوا، \nهو كان بيعمل كده من قلبه لأنه كان عايز الثواب من عند ربنا وبس، ومكنش يعرف إن عمله ده هينجيه في يوم من الأيام\n¤طبعا السؤال إللي كلنا ممكن نسأله، وهو يعني من الرحمة إنه يسيب عياله يعيطوا من الجوع كده وهو واقف\nطب ما كان يسقيهم وخلاص \nبعض العلماء قالوا إن كان في شرع الرجل ده إن النفقة على الأب والأم ورعايتهم مقدمة على النفقة على الأبناء،\nوعلماء قالوا إن الأطفال كانوا بيطلبوا حاجة زيادة عن حاجتهم فلم يعطها لهم،\nيعني زي ما عيالنا بيعملوا، نبقى مأكلينهم ومشربينهم وشبعانين ويشوفوا حاجة عايزينها يقعدوا يعيطوا عليها عشان يأخذوها\nفالرجل مرضاش أبدا إن حد يشرب من اللبن قبل أبويه \nوهو كان فعلا صادق ومخلص في عمله، لأن مفيش هنا حد يُرائيه،\nمفيش حد معاه غير مراته، والرجل في العادة لا يُرائي زوجته؛ لأنها ليل نهار معاه فعارفة كل حاجة عنه وحافظاه\n◇نشوف الثاني، قال:\nيارب انت عارف إن أنا كان عندي ابنة عم كنت بحبها كأشد ما يحب الرجال النساء، فحصلت لها مجاعة وكانت محتاجة فلوس فجاءتني تطلب مني مالا فراوَدتها عن نفسها، فرفضت ولم تقبل،《كان عايز يزني بها》\nفجاءتني مرة تانية تطلب مني المال فراودتها عن نفسها فرضيت بمائة دينار، فجمعتها لها وتعبت على ما جمعتهم لها...\n◇المرأة كانت راحت تدور على حد تاني يساعدها ملقتش، فرجعت تاني لابن عمها تطلب منه المال لأن مكنش في حد غيره يقدر يساعدها.\nفلما قعدتُ منها مقعد الرجل من امرأته قالت لي:\nيا عبد الله، اتق الله ولا تفُضّ الخاتم إلا بحقه،\n《يعني مينفعش تمارس معايا العلاقة الزوجية إلا بعقد شرعي صحيح》\nفقمت عنها ولم أزنِ بها وهي أحب الناس إلى قلبي، وتركت لها المال،\nاللهم إن كنت تعلم أني فعلت هذا ابتغاء مرضاتك ففّرج عنا ما نحن فيه\nفتحركت الصخرة حاجة بسيطة لكنهم لسه مش عارفين  يخرجوا.\n☆أكبر فتنة الرجل ممكن يتعرض لها هي المرأة زي ما رسول الله ﷺ قال:\n\"مَا تَرَكْتُ بَعْدِي فِتْنَةً أَضَرَّ عَلَى الرِّجَالِ مِنْ النِّسَاءِ\"\nوده لأن ربنا خلق الرجل بطبعه إنه يميل للمرأة،\nمتجيش واحدة تقولي طب واحنا ذنبنا إيه يعني نتكتف بحجاب ومنخرجش براحتنا عشان خاطر الرجل\n الدنيا يا جماعة دار ابتلاء وامتحان، يعني إللي بيطيع ربنا ويبعد نفسه عن الوقوع في الحرام هيدخل الجنة،\nوإللي هيمشي وراء هواه ويقع في الحرام مصيره إلى النار،\nفزي ما الرجل طبيعته إنه يميل للمرأة ويجب عليه إنه يمنع نفسه من الوقوع في الحرام ويجب عليه غض بصره،\nالنساء برده من طبيعتها حب الزينة وإنها تظهر الزينة دي للناس،\nفيجب عليها إنها تقاوم ميلها الفطري للزينة وتلتزم بأمر الله، لأنها هي كمان في ابتلاء،\nفربنا بيبتلي كل واحد على حسب طبيعة تكوينه وفي الحاجة إللي بيحبها وشديدة عالنفس\nماهو معلش يعني، هو فين الابتلاء إن ربنا يمنع عني حاجة أنا كارهاها\nلما أكون مثلا مش بحب أكلة معينة وألاقي أمي في يوم تقول لي طيب أنا مش هعملك الأكلة الفلانية كنوع من العقاب عشان مسمعتش كلامها في حاجة هيبقى رد فعلي إيه\nأكيد هقول لها بركة يا جامع أنا أصلا مبحبهاش\nلكن تعالي كده خليها تمنعك عن مشوار مهم ولّا خروجة مع أصحابك كنتِ مستنياها وبتخططي لها، شوفي رد فعلك هيبقى عامل إزاي\nفالابتلاء اسمه ابتلاء لأننا بنعمل حاجة أو بنقاوم حاجة ضد رغباتنا وضد هوانا،\nفربنا جعل فتنة الرجال وابتلاؤهم الأشد في النساء،\nوشوفوا الشعراء وكلامهم عن النساء وقصص حب عنتر وعبلة وغيرهم،\nوهنروح بعيد ليه، انتم شايفين الواقع بتاعنا وحال الشباب والبنات\nوحتى رسول الله ﷺ كان بيقول للنساء:\n\"مَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَذْهَبَ لِلُبِّ الرَّجُلِ 《الْحَازِمِ 》مِنْ إِحْدَاكُنَّ\" \nيعني مش راجل كده وخلاص، ده الرجل الحازم إللي يَغلب ولا يُغلب، المرأة بقى تغلبه وتضيع عقله\nفتخيلوا بقى لما يكون شاب بيحب امرأة الحب الشديد ده بقاله سنين، ماهي بنت عمه\nوكمان مع الميل الفطري للنساء وكان خلاص تمكّن من المرأة ومفيش أي مانع يمنعه إنه يزني بها، \nيقوم عنها وكمان يترك لها المال إللي تعب في تجميعه، وكل ده عمله لله وكان مُخلص فيه عشان كده ربنا استجاب له وحرك لهم الصخرة شوية\nاتبقى عندنا الرجل الثالث، يا ترى قال إيه، \nوهل خرج الثلاثة من الغار بعد كده، وإيه حكاية صاحبة الوشاح الأحمر دي\nده إللي هنعرفه الجزء الجاي إن شاء الله\n☆ ملحوظة مهمة\nالأحداث إللي بحكيها عن رسول الله ﷺ مع الصحابة، بحكيها بصفة عامة مش خاصة بزمن محدد\nيعني قصة أصحاب الغار إللي رسول الله ﷺ حكاها للصحابة  مكنش وقتها بعد غزوة أُحد بالضبط،\nوكذلك لما حكيت قبل كده عن قصة قاتل المائة نفس،\nأنا معرفش الأحداث دي كان وقتها امتى بالضبط، \nلكن أنا بقول لكم أمثلة عن حياة رسول الله ﷺ مع الصحابة كانت عاملة إزاي؛ عشان نتعلم ونقدر نطبق ده في حياتنا،\nوفي قصص تانية هقولها، بس إللي رواها صحابة تأخر إسلامهم،\nفهقولها بعد ما نعرف إنهم أسلموا، وأنا بحاول أراعي زمن الأحاديث والأحداث بين رسول الله ﷺ والصحابة داخل المدينة على أد ما أقدر،\nلكن الغزوات والسرايا زمانها معروف فمفيش فيها مشكلة\n♡"}, {"n": 107, "l": "الجزء 81 | الإخلاص | وقصة أصحاب الغار الجزء الثاني | وصاحبة الوشاح الأحمر", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_\n#الحلقة_الواحدة_والثمانون\n#الإخلاص_وقصة_أصحاب_الغار_الجزء_الثاني\n#قصة_صاحبة_الوشاح_الأحمر\nاتكلمنا المرة إللي فاتت عن الثلاثة رجال إللي دخلوا غار ونزلت صخرة سدت عليهم باب الغار،\nوشوفنا إن كل واحد فيهم دعا ربنا بأكثر عمل صالح كانوا محققين فيه الإخلاص عشان ربنا ينجيهم من الموت المُحقّق،\nالأول كان عمله هو بِرّه بأبويه، والثاني كان إنه استعفف عن الزنا،\nالثالث بقى هو إللي هنتكلم عنه النهاردة إن شاء الله \nخلونا نشوف الثالث دعى بإيه\nقال:\nيارب انت عارف إن كان عندي أُجراء، يعني ناس فواعْلية بيشتغلوا باليومية، \nاستأجرتهم على مِكيال من أَرُز أو ذرة يعني في مقابل إني أدفع لهم مكيال محدد من الرز أو الذرة، فلما أعطيتهم أجورهم واحد منهم قال:\nأنا اشتغلت شغل رجلين مش واحد، فأنا عايز أجر رجلين مش أجر واحد \nفقلت له: احنا متفقناش على كده وأنا مظلمتكش في حاجة\n فمرضيش وترك نصيبه وانصرف،\nفثمّرته له《يعني شغّل له نصيبه، زي ما واحد بيعطي فلوس لواحد يشغلها له》\nحتى اشتريت بها بقر وغنم وإبل وبقى عندي وادي مليان بهم، فجاءني الرجل بعد زمان وكانت حصلت له مشكلة ومحتاج فلوس فتذكر إن كان له مال عندي فجاءني وقال لي:\nيا عبد الله رجّع لي حقي ولا تجْحَدني،\n فقلت له :\nشايف إللي قصادك ده كله من البقر والغنم والإبل، ده كله مالك وحقك\nفقال لي: يا عبد الله اتق الله ولا تستهزئ بي\nفقلت: أنا لا أستهزئ بك، كل ده فعلا بتاعك \nفالرجل أخذ كل حاجة ومشي، \nفاللهم إن كنت تعلم أني فعلت هذا ابتغاء مرضاتك ففرّج عنا ما نحن فيه \nفتحركت الصخرة وخرجوا هم الثلاثة من الغار\n☆الرجل الثالث ده حكاية\nليه\nالإنسان بطبيعته بيحب المال، ربنا بيقول:\n \"وإنه لحب الخير لشديد\"\n الخير هنا معناها المال،\nحتى رسول الله ﷺ بيقول:\n\" لو أن لابن آدم واديٍا من ذهب لابتغى إليه ثانيا ولو أُعطى ثانيا لابتغى إليه ثالثا ولا يملأ جوف ابن آدم إلا التراب، ويتوب الله على من تاب\"\nوالوادي يعني منتهى البصر، يعني هنا مفيش أرقام، تخيلوا  مليارات من الأموال،\nفالإنسان لما يشوف الوادي ده، يقول يا سلام لو واحد كمان جنبه\nفدي حاجة في أصل خِلقة البشر، فالإنسان لا يشبع أبدا من حب المال،\nولو لاحظتم هتلاقوا إن معظم العداوات بين الناس بسبب المال،\nفتخيلوا بقى واحد بيحب المال بالطريقة دي وقعد يتاجر في كيلو ولّا اتنين كيلو رز ويبيع ويشتري لحد ما ملأ وادي كامل بالبقر والأغنام من تجارة الكيلو رز ده\nمتصورين الوقت والجهد إللي عمله عشان يكوّن الثروة دي\nوالتاني جاء أخذ كل حاجة على الجاهز كده وحتى من غير ما يقول له طب خذ نص الوادي على أد تعبك إللي تعبته، \nولّا خُذ لك بقرة ولا اثنين...مفيش\nأخذ كل حاجة وصاحبنا حتى معترضتش عليه، ولا قال له طيب فين حق السنين إللي تعبتها دي، تركه يأخذ كل شيء ومشي\nفهو استطاع إنه يتغلب على شهوة حب المال المُركّبة في أصل خلقته ويرقى بنفسه لقمة الإيمان ده\nمع العلم إن الشخص ده مش نبي، يعني ربنا لم يُعطه قدرات خاصة فهنقول أه ما هو ربنا ساعده وشال من قلبه حب المال،\nلأ...ده بشر عادي زيه زينا بالضبط \nوهنا نتعلم إننا نقدر نتغلب حتى على الشهوات إللي في أصل خلقتنا،\nزي ما قلنا المرة إللي فاتت عن حب النساء للزينة، وإنها لازم تقاوم مِيلها الفطري للزينة قصاد الناس من غير محارمها، وحب الرجل للنساء، وقيسوا بقى على كده\nعارفين،\nاحنا ممكن لما نحط نفسنا مكان الرجل نحس بضيق لأن هو عمل مجهود كبير جدا عشان يُنمي الفلوس دي وفي الآخر مأخدش أي جزاء على مجهوده،\nوكل إللي تعب فيه سنين نقدر نقول إنه راح في لحظة،\nتخيلوا إن ده بالضبط إللي بيحصل لما بنغتاب حد\nيعني الواحد يقعد يتعب ويجتهد في العبادة، ويجاهد نفسه عشان يحقق الإخلاص ويعالج الرياء والعُجب،\nويدرب نفسه على الخشوع ويجاهد نفسه في قراءة القرآن وقيام الليل في البرد والحر،\nوفي الآخر بكل سهولة واحد تاني يأخذ كوووول ده بسبب إني اتكلمت عليه بسوء، أو ذكرت عيوبه أو...أو...\nالموضوع مرعب بجد؛ لأن الشخص إللي بنغتابه مش هياخد أي حسنات عملناها\nده هياخد من الحسنات إللي ربنا تقَبّلها واتكتبت في الصحيفة بتاعتنا، \nفأنا عايزاكم تتخيلوا كده واحد بيشتغل طول النهار وتعبان جدا وأول يوم أخذ فيه المرتب جه واحد وأخذه منه كده بكل بساطة وهو ملوش أي حق إنه يتكلم أو يحاول يسترجع المال ده، إحساسه هيبقى عامل إزاي\nطبعا قمة القهر والزعل، لكن الإنسان ممكن يشتغل ويعوض الفلوس دي تاني،\nلكن يوم القيامة بقى هتبقى حسرة ما بعدها حسرة لما الواحد يشوف حسناته وهي بتتاخد منه وتروح لفلان وهو بيشوف درجته في الجنة عمالة بتنزل ..بتنزل..ومفيش أي مجال إنه يعوض الحسنات دي خلاص الدنيا انتهت ومفيش رجوع لها تاني\nومش بعيد حسناته تخلص وياخد من سيئات الناس إللي اغتبها ويبقى في صحيفته زنا وسرقة وكذب ومشاهدة حرام مع إنه معملش كل ده، وكان بعيد كل البعد عن المعاصي\nلكنها الغيبة\nرسول الله ﷺ يقول:\n\"أَتَدْرُونَ مَا الْمُفْلِسُ ؟ قَالُوا : الْمُفْلِسُ فِينَا مَنْ لا دِرْهَمَ لَهُ وَلا مَتَاعَ \n فَقَالَ : إِنَّ الْمُفْلِسَ مِنْ أُمَّتِي يَأْتِي يَوْمَ الْقِيَامَةِ بِصَلَاةٍ وَصِيَامٍ وَزَكَاةٍ ، وَيَأْتِي قَدْ شَتَمَ هَذَا ، وَقَذَفَ هَذَا ، وَأَكَلَ مَالَ هَذَا ، وَسَفَكَ دَمَ هَذَا ، وَضَرَبَ هَذَا ،\nفَيُعْطَى هَذَا مِنْ حَسَنَاتِهِ ، وَهَذَا مِنْ حَسَنَاتِهِ ، فَإِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ أَنْ يُقْضَى مَا عَلَيْهِ أُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَتْ عَلَيْهِ ثُمَّ طُرِحَ فِي النَّارِ\n☆طيب ببقى متضايق وهطق وعايز أفضفض، أعمل إيه\nمضايق من حد اشتكيه لربنا واحكيله عن كل حاجة مضايقاك منه ربنا هيريح قلبك،\nلأن قلبك بإيده وكل إللي بيحصل لك ربنا مقدره عليك فهو إللي بإيده يغير لك كل حاجة ويراضيك، وكمان لما تفضفض لربنا هتتعلم التوكل عليه واليقين والكلام إللي هتقوله مش هيبقى غيبة \nفاكرين يعقوب عليه السلام كان بيقول إيه؟\n\" إِنَّمَا أَشْكُو بَثِّي وَحُزْنِي إِلَى《 اللَّهِ》\"\nودايما افتكر كده إن إللي بتتكلم عليه ده هياخد حسناتك  إللي قعدت تجاهد نفسك عشان تحقق فيها الإخلاص وتزينها لربنا عشان يتقبلها منك\nوكفارة الغيبة إنك تذكر نفس الشخص إللي اغتبته بخير في نفس المجلس إللي اغتبته فيه وتدعي له بظهر الغيب،\nرسول الله ﷺ يقول:\n\"مَنْ كَانتْ عِنْدَه مَظْلمَةٌ لأَخِيهِ مِنْ عِرْضِهِ أَوْ مِنْ شَيْءٍ فَلْيتَحَلَّلْه ِمِنْه الْيَوْمَ قَبْلَ أَلَّا يكُونَ دِينَارٌ وَلَا دِرْهَمٌ، \nإنْ كَانَ لَهُ عَمَلٌ صَالِحٌ أُخِذَ مِنْهُ بِقَدْرِ مَظْلَمتِهِ، وإنْ لَمْ يَكُنْ لَهُ حسَنَاتٌ أُخِذَ مِنْ سيِّئَاتِ صاحِبِهِ، فَحُمِلَ عَلَيْهِ\"\nومش لازم أبدا إن أروح أقول له يا فلان أنا اغتبتك سامحني، هنا هتحصل مشكلة أكبر\n♡ونصيحة مني للي يقدر عليها،\nدايما بينك وبين ربنا اعفو عن أي حد اغتابك أو شتمك أو زعّلك عشان يوم القيامة ربنا يعاملك بالمثل ويعفو عنك، والجزاء من جنس العمل\nوهقول لكم على حاجة حلوة\nلو أنا مسامحتش إللي اغتابني أو شتمني أو...أو...هاجي يوم القيامة وأخذ من حسناته على أد الغيبة إللي هو عملها بالضبط، يعني حسنات معدودة\nلكن بقى لو أنا سامحته في الدنيا وكمان أحسنت له وقابلت إساءته بإحسان، هاخد إيه\nربنا هو إللي هيعطيني أجر عظيم غير محدود ولا معروف من الحسنات وربنا نفسه إللي قال لنا كده \n\"فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ\"\nشوفتم 《فَأَجْرُهُ عَلَى اللَّهِ دي》\n كل ما ربنا يريد إنه يُعظّم من أجر يُخفي كمية الأجر ده، فمين بقى إللي يضيّع أجر ربنا العظيم في مقابل شوية حسنات معدودة\nقبل ما نعرف قصة صاحبة الوشاح الأحمر في كم سؤال محتاجين نعرف إجابتهم\n◇هم الثلاثة رجال دول عرفوا إزاي إنهم مخلصين؟\n يعني هو الإنسان ممكن يعرف إذا كان مخلص فعلا ولّا لأ\nوممكن يحقق الإخلاص في عمله والإخلاص ده مش حاجة مستحيلة\nخلونا الأول نفهم قاعدة مهمة وهي إن ربنا بيقول :\n\"وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ\"\nيعني كل أمور الدين ربنا جعلها سهلة علينا ومش صعب تحقيقها،\nواحنا عارفين إن الإخلاص شرط لقبول العمل، يعني لو مفيش إخلاص مفيش قبول والعمل هيحبط،\nطيب حاجة بالخطورة دي إزاي تكون صعبة أو مستحيل نحققها\nيبقى تحقيق الإخلاص مش حاجة مستحيلة ونقدر فعلا نحققها لو درّبنا نفسنا عليها،\nبكل بساطة قبل ما نعمل أي عمل صالح هنقف مع نفسنا ونفكر:\nهو أنا بعمل العمل الصالح ليه؟\nبصلي ليه...بصوم ليه...بتصدق ليه...بقرأ واحفظ قرآن ليه....ليه...ليه...\nهنجاوب على نفسنا أنا بعمل العمل الصالح عشان:\nربنا أمرني بكده، عشان عايز أتقرب لربنا، عشان عايز رحمة ربنا، عشان عايز أنجو من النار وأدخل الجنة\nجاوبنا على نفسنا، على طول بقى نعمل العمل الصالح وإن شاء الله نكون مخلصين في العمل\n◇طيب، الناس بقى إللي في نص العمل الصالح يدخل لها الشيطان ويقول لهم أيوة اعمل عشان فلان يقول عليك كذا وكذا،\nاعمل عشان الناس تحترمك وتحبك اعمل عشان وعشان من الأسباب الدنيوية، ويقعد يشككه في نيته ويقول له انت اصلا مُرائي\nساعتها بقى نعمل إيييه\nهنعمل زي ما رسول الله ﷺ قال لنا، هندفع الوسواس ده ونستعيذ بالله من الشيطان الرجيم وندعي ونقول:\n\" اللهم إني أعوذ بك أن أُشرك بك شيئًا وأنا أعلم وأستغفرك لما لا أعلم\"\nاحفظوا الدعاء ده وقولوه لأن رسول الله ﷺ قال عنه إنه بيبعد الإنسان عن الرياء، والرياء هو الشرك الأصغر\nإللي هيعمل إللي قلته ده هيكون مخلص إن شاء الله ويحقق شرط الإخلاص في عمله عشان ربنا يتقبله\nالموضوع سهل والله يا جماعة بس محتاج تدريب وتركيز مش أكثر،\nولازم نفهم كويس جدا إن مفيش حد هيدخل الجنة بعمله أبدا ولا حتى رسول الله ﷺ، لكن هي رحمة ربنا بينا،\nورحمة ربنا دي لمن يتقي الله ويعمل الصالحات،\n\" وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ ۚ فَسَأَكْتُبُهَا لِلَّذِينَ《 يَتَّقُونَ》 \"\nفالعمل مطلوب عشان ربنا أمرنا إن احنا نعمل بس مش أكثر\nبعد ما عرفنا إن تحقيق الإخلاص في العمل مش حاجة مستحيلة ونقدر نعملها،\nنسأل نفسنا بقى، لو أنا كنت الرابع مع الثلاثة دول ومطلوب مني إني أتوسل إلى الله بعمل صالح كنت هقول إيييه\n هل أنا عندي العمل الصالح إللي ينجيني فعلا من الهلاك،\nولّا معنديش وكنت هبقى سبب في هلاك نفسي وهلاكهم معايا\nلو عندي فذلك فضل الله نحمد ربنا عليه\nطيب لو معنديش\nبكل بساطة يبقى أعمل الأعمال الصالحة إللي تنجيني من الهلاك سواء في الدنيا أو في الآخرة\nمادام احنا لسه على قيد الحياة وبنتنفس يبقى لسه في فرصة للتغيير وفرصة للأعمال الصالحة\nمحدش ييأس يا جماعة العبرة بالخواتيم، أحسن فيما بَقِي يُغفر لك ما مضى، أهم حاجة نستغل الفرصة صح\nقصة أصحاب الغار بتعلمنا إن الأعمال الصالحة في وقت الرخاء بتفيد الإنسان في وقت الشدة، \nمش رسول الله ﷺ بيقول:\n\" تعرّف إلى الله في الرّخاء يعرفك في الشدة\"\nيعني إللي يطيع ربنا ويتقيه ويقف عند حدوده وينفذ أوامره ويبعد عن إللي نهى عنه في وقت ما هو عايش في النعم،\nلما تحصل له مشكلة أو ابتلاء ربنا هينجيه من الفتن والابتلاءات والشدائد دي\nوهنا نفتكر مين\nصاحب الحوت يونس عليه السلام إللي ربنا قال عنه:\n\"فَلَوْلا أَنَّهُ كَانَ مِنَ الْمُسَبِّحِينَ\"\nممكن ترجعوا لقصة يونس عليه السلام في قصص الأنبياء عشان تفتكروا قصته وتفهموا المعنى أكثر\n◇الكلام هياخدنا لسؤال تاني مهم \nهل لو أنا توسلت إلى الله بالأعمال الصالحة في الدنيا، كده خلاص أجرها راح ومش هيبقى لي نصيب من الأجر في الآخرة\nشوفوا، \nالدعاء والتوسل إلى الله بالأعمال الصالحة في الدنيا زي أصحاب الغار كده لا ينقص من ثواب الأعمال الصالحة في الآخرة، ربنا بيقول:\n\"وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ\"\n\"وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مِنْ أَمْرِهِ يُسْرًا\"\nفالله جعل الأعمال الصالحة سبب لسعادة الإنسان في الدنيا والآخرة\nلااااااكن\nإللي بيعمل الأعمال الصالحة عشان الدنيا من البداية، أو عشان يرجع يتوسل إلى الله عشان عايز مصلحة دنيوية فده أجره بينقص في الآخرة على قدر هم الدنيا في قلبه،\nفكل ما كان غرضه من العمل الصالح هو الدنيا في 《الأساس》مع الأجر في الآخرة قَل أجره في الآخرة،\nلكن إللي مش بيفكر في الآخرة أصلا وكل همه من العمل الصالح إنه يحقق مصالح الدنيا فده ملوش أجر أصلا في الآخرة ويحبط عمله\n\"مَّن كَانَ يُرِيدُ الْعَاجِلَةَ عَجَّلْنَا لَهُ فِيهَا مَا نَشَاءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُ جَهَنَّمَ يَصْلَاهَا مَذْمُومًا مَّدْحُورًا\"\n◇إيه ده \nيعني أنا لما بستغفر وأكثر من الصلاة على رسول الله ﷺ بنية إن ربنا يفرج كربي ولّا يزيل همي يبقى كده أجري هينقص في الآخرة\nطبعا لأ\nلأن ده أصلا من الدعاء المشروع إللي ربنا أمرنا به ووعدنا بأجره،\n\"مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُ حَيَاةً طَيِّبَةً ۖ وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا يَعْمَلُونَ \"\nفالمشكلة بس لما الإنسان يكون بيستغفر ويصلي ويتقرب إلى الله بالطاعات عشان يزيل همه ويفرج كربه،\nوأول ما يحقق إللي هو عايزه خلاص يسيب الطاعات والاستغفار وكل الصالحات،\nأو مثلا ملقاش نتيجة للاستغفار والأعمال الصالحة فيقوم سايب كل ده،\nفهنا بقى ده إللي ينطبق عليه الكلام الأول\n¤ملحوظة مهمة جدا\nالتوسل يكون بالأعمال الصالحة فقط، يعني بأي عمل صالح، مينفعش التوسل بأولياء الله الصالحين، مينفعش التوسل بجاه النبي، مينفعش التوسل بالزمن،\nيعني مفيش حد ييجي يقول: يارب بحق الأيام المُفترجة دي اغفر لي مثلا،\nكل ده من التوسل الغير مشروع وممكن يدخل في الشرك واحنا مش واخدين بالنا\n◇ندخل في السؤال ثالث \nهو ينفع الإنسان يدعو ويتوسل إلى الله 《 بنفس》 العمل أكثرة من مرة\nمفيش مشكلة خالص إن الإنسان يتوسل بنفس العمل الصالح أكثر من مرة لأنه دعاء مشروع ونتقرب به إلى الله، ما هو مش كارت شحن يا جماعة هنستعمله مرة واحدة وخلاص خلص\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ \"\n《للتفصيل أكثر هتلاقوا في موقع الإسلام سؤال وجواب قصة أصحاب الغار للشيخ أبو إسحاق الحويني》\n♡قصة أصحاب الغار بتعلمنا إن المسلم لازم يلجأ بالدعاء إلى الله وحده وخصوصا وقت الشدائد،\nوربنا وعد بإجابة الدعاء لأي حد يدعوه، ووعد بإجابة دعوة المضطر حتى ولو كان كافر،\n\"أَمَّن يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ وَيَجْعَلُكُمْ خُلَفَاءَ الْأَرْضِ ۗ أَإِلَٰهٌ مَّعَ اللَّهِ ۚ قَلِيلًا مَّا تَذَكَّرُونَ\"\nوده ياخدنا على طول لقصة صاحبة الوشاح الأحمر\nكان في حي من أحياء العرب القديمة أسرة من الأغنياء، وكان عندهم جارية سوداء بتخدمهم، انتم عارفين العبيد والإماء كانوا منتشرين في عهد رسول الله ﷺ،\nفالأسرة الغنية دي أعتقت الجارية، لكن الجارية مكنش عندها بيت ولا تعرف حد ولا لها أي مكان تروحه، \nفاستمرت الجارية دي تخدم الأسرة الغنية في مقابل إنها تعيش معاهم ويأكّلوها معاهم يعني،\n المهم، في يوم من الأيام خرجت بنت صغيرة من بنات الأسرة دي عشان تروح الحمام،\nوالحمام في زمانهم معناه مكان معمول للناس عشان يستحموا فيه، مش معناه الحمام بتاعنا دلوقتي \nفالبنت دي كان عليها وِشاح لونه أحمر، والوشاح هو قماشة طويلة بتتلف حول الرقبة زي كده \n البنت دخلت الحمام وتركت الوشاح خارج الحمام،\nكان في حِدَأَة بتطير، يعني حِداية، وهي طائر يشبه الصقر\nكده تقريبا\n \nالحِدَأة شافت الوشاح الأحمر فكرته حتة لحمة، راحت نازلة عليه خطفته وطارت،\nالبنت خرجت من الحمام ملقتش الوشاح بتاعها، راحت تعيط لأهلها، دوروا عليه مش لاقيينه\nفاتهموا الجارية السوداء بإنها سرقته، وقعدوا يفتشوها لدرجة إنهم قلعوها هدومها وفتشوا في جسمها، وهي تقول لهم إنها لم تأخذه وهم مش مصدقينها،\nالجارية حست بالظلم والمهانة والضعف، ملهاش حد يدافع عنها ولا يثبت براءتها، وهي ضعيفة مش عارفة تدافع عن نفسها،\nفالجارية السوداء ملقتش غير إنها تدعو الإله إللي في السماء، وهي كانت أصلا بتعبد الأصنام،\nلكن زي ما ربنا قال عن المشركين، إنهم لما يكونوا في كرب وبلاء بيدعو الله مخلصين له الدعاء ويتركوا آلهتهم\n\" فَإِذَا رَكِبُوا فِي الْفُلْكِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ إِذَا هُمْ يُشْرِكُونَ \"\nالجارية قعدت تدعو الله من كل قلبها إنه يظهر براءتها ويخلصها من المشكلة إللي هي فيها دي،\nفاستجاب الله لها في نفس اللحظة إللي دعت فيها\nالحدأة رجعت بالوشاح ورمته عليهم وهم واقفين،\nتخيلوا منظر الناس وهم ماسكين في خناق الجارية وفجأة يلاقوا الوشاح بيترمى عليهم من السماء\nوبكده ظهرت براءة الجارية السوداء، فأخذوا الوشاح وراحت الجارية مزعقة فيهم:\nاتهمتوني ظلم إن أنا إللي سرقته وأهه قصادكم أهه\nفقررت الجارية إنها تهاجر من البلد دي بعد ما الموقف ده أثّر فيها جدا، لكن تروح فين؟ ملهاش حد\nفعرفت إن في واحد بيقول إنه رسول من عند الله، فهاجرت إلى المدينة، وذهبت لرسول الله ﷺ وأعلنت إسلامها وعملت لها خيمة في المسجد وسكنت فيها،\nوكانت دائما بتنشد بيتين من الشعر بتقول فيهم:\nويَوْمُ الْوِشَاحِ مِنْ أعَاجِيبِ رَبِّنَا\nإلَا إِنَّهُ مِنْ بَلْدَةِ الْكُفْرِ أَنْجَانِي\nفسألتها السيدة عائشة مرة إيه يوم الوشاح ده، وليه بتقولي الأبيات دي على طول\nفحكت لها الجارية قصتها مع الوشاح ومع استجابة ربنا لدعائها وهي كانت لسه مشركة\nتخيلوا إن ده استجابة ربنا لدعاء المضطر الكافر، فما بالكم بدعاء المضطر إللي بيقول لا إله إلا الله\nادعوا ربنا يا جماعة : \"إِنَّ رَبِّي قَرِيبٌ مُّجِيبٌ \"\nإن شاء الله الجزء الجاي هنتكلم فيه عن رسول الله ﷺ وبعض مواقفه مع زوجاته وبعض مواقفه مع أصحابه \n♡ملحوظة عايز أقول عليها\nالهدف إللي أنا عايز أحققه من حكاية قصص الأنبياء ومن حكاية السيرة بالذات، \nهو إني أَعرّف القارئ مَن هو رسول الله ﷺ، عشان أزرع في قلبه حب رسول الله ﷺ وحب الصحابة،\nوكمان عشان القارئ يعرف دينه، أنا مش بحكي قصة وخلاص، إللي عايز قصة فقط هيلاقي محاضرات كثيرة وكتب كثيرة بتحكي قصة حياة رسول الله ﷺ، \nلكن أنا هدفي هو تعليم الناس أساسيات الدين من خلال شرح قصص الأنبياء والسيرة النبوية،\nوانتم شايفين الناس معندهاش حتى المعلومات الأساسية عن دينها، وحتى مكسلين يتعلموا\nفأنا مش عايزاكم تزهقوا يا جماعة، ووعايزاكم تطولوا بالكم معايا\nإن شاء الله على ما نخلص السيرة هتطلعوا منها بكمية معلومات كثيرة جدا مكنتوش هتعرفوها لو أنا حكيت فقط مجرد أحداث وراء بعضها وخلاص،\nبحاول أخليكم تحسوا كأنكم كنتم عايشين مع الصحابة، \nكأنكم جزء منهم، عايشين لنفس هدفهم، بنتربى معاهم  وإللي بيربينا رسول الله ﷺ،\nطبعا أنا بحاول على أد ما أقدر أعمل كده، والفتح والتوفيق من عند ربنا،\nفجزاكم الله خيرا على صبركم واستمراركم معايا، وربنا يجمع بيننا يوم القيامة مع رسول الله ﷺ يسقينا من حوضه ونستظل بظل عرش ربنا عز وجل\n♡"}, {"n": 108, "l": "الجزء 82 | قصة المقداد _ولبن _رسول الله | رسول الله مع سوده وعائشه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثانية_والثمانون\n#قصة_المقداد_ولبن_رسول_الله\n#رسول_الله_مع_سودة_وعائشة\nهنتكلم النهاردة عن بعض مواقف رسول الله ﷺ مع أصحابه وبعض زوجاته،\nواحد من الصحابة اسمه المِقداد بن الأسود، أو خلينا نقول اسمه إللي هو مشهور به المقداد بن عمرو،\nفاكرينه\n إللي قال لرسول الله ﷺ في غزوة بدر لما كان بيستشير الصحابة يقاتلوا ولّا يرجعوا للمدينة فقال المقداد بن عمرو:\nيا رسول الله! اعمل إللي إنت شايفه صح،\nفوالله مش هنقول لك كما قال بنو إسرائيل لموسى اذهب أنت وربك فقاتلا فإنا هاهنا قاعدون،\nولكن هنقول لك : اذهب أنت وربك فقاتلا إنا معكما مقاتلون وكان رسول الله ﷺ فرح بكلامه جدا\nحصل موقف بين رسول الله ﷺ وبين المقداد بن عمرو هيحكيه لنا المقداد، يقول:\nأنا واثنين من أصحابي كنا جعانين جدا لدرجة إن تركيزنا راح، لا شايفين ولا سامعين حاجة،\nفعرضنا أنفسنا على أصحاب النبي ﷺ عشان يضيفونا ويأكلونا فمحدش منهم قَبِلَنا\n☆قلنا قبل كده إن الصحابة كانوا فقراء جدا، كان ممكن الواحد يقعد بالأيام مياكلش وكانوا بيربطوا الحجر على بطونهم من شدة الجوع،\nفكل إللي عرضوا نفسهم عليهم كانوا فقراء زيهم ومعندهمش إللي يكفي الثلاثة دول.\nفالثلاثة راحوا لرسول الله ﷺ، فأخذهم رسول الله ﷺ وذهب لأهله ،فلقى عندهم ثلاثة أَعْنُز، ماعز يعني،\nفقال لهم احلبوا الماعز الثلاثة واقسموا اللبن بيننا احنا الأربعة، \nفكانوا بيحلبوا اللبن ويشربوا ويتركوا نصيب رسول الله ﷺ  متغطي في جنب لحد ما ييجي ويشربه،\nاستمر الوضع كده كام يوم، وكان رسول الله ﷺ بيذهب للأنصار ولما يخلّص مشواره يرجع بالليل ويقعد يصلي في المسجد وبعدها ييجي يشرب اللبن بتاعه،\nفي يوم من الأيام بعد ما شربوا نام الاثنان ولم ينم المقداد كان لسه جعان ومفيش غير نصيب رسول الله ﷺ بس هو إللي فاضل، فيقول:\nوأنا نايم على الأرض كده جاءني الشيطان يوسوس لي وقال لي:\nمحمد بيروح للأنصار، فأكيد يعني مش هيسيبوه من غير أكل وهيضيّفوه، فأكيد مش هيبقى محتاج لشوية اللبن دول،\nقوم اشرب قوم\nفلما أغراه الشيطان وأقنعه إن رسول الله ﷺ مش محتاج شوية لبن قام المقداد بن عمرو وشرب نصيب رسول الله ﷺ من اللبن،\nوأول ما دخل اللبن جوفه وعرف إن خلاص مفيش مجال إنه يرجع اللبن ده تاني، الشيطان مسابوش وقعد يندّمه\nقال له: انت عملت إيه\nشربت اللبن بتاع محمد\nدلوقتي ييجي عشان يشرب اللبن بتاعه وميلاقيهوش، فيدعو عليك وتضيع عليك دنياك وآخرتك\nفطار النوم من عين المقداد وقعد قلقان وغطى نفسه بشَمْلة،\nغطاء زي لحاف صغير كده، كان لما يغطي رأسه رجل تبان،\nلو غطى رجله رأسه تبان،\nوهو على الحالة دي جاء رسول الله ﷺ \nوكان من عادته لما ييجي إنه يُسلم سلام ميصحيش النائم وإللي صاحي يسمع سلامه،\nفسلم رسول الله ﷺ كعادته وصلى في المسجد، وراح يكشف عن الطبق إللي فيه اللبن بتاعه عشان يشربه، فلما كشفه ملقاش فيه حاجة، فرفع إيده يدعي،\nوكل ده والمقداد باصص على رسول الله ﷺ من تحت الشملة بتاعته ورسول الله ﷺ ميعرفش حاجة\nفلما شافه المقداد بيرفع إيده للسماء عشان يدعي قال في نفسه: \nبس كده أنا خلاص هلكت...روحت في داهية\nفقعد يسمع رسول الله ﷺ هيدعي بإيه،\nفسمعه يقول : اللهم أطعم من أطعمني واسقِ من سقاني\nفقام المقداد وأخذ سكينة وذهب إلى الأَعْنز عشان يذبح منهم واحدة ويُطعم رسول الله ﷺ ويبقى الدعاء إللي رسول الله ﷺ دعاه من نصيبه،\nفلقى المقداد الضرع بتاع الأعنز كلهم مليان لبن، فأتى بطبق كبير عميق لا يتصور آل محمد ﷺ إنهم يحلبوا فيه ولا حتى يملوه زي ماهو بيحكي،\nفحلب الأعنز وملأ الطبق باللبن لدرجة إن رغوة اللبن عِليت عن الطبق\nفأخذ اللبن وراح لرسول الله ﷺ، فرآه رسول الله ﷺ وأكيد استغرب إن المقداد لسه صاحي \n فقال له المقداد وهو بيعطيه اللبن:\nاشرب يارسول الله \nفرسول الله ﷺ سأله: هل شربتم؟\nفقال له المقداد: اشرب \nطبعا مجاوبهوش\nهو مش عايز رسول الله ﷺ يعرف حاجة لحد ما يخلص عشان يأخذ بركة دعاء رسول الله ﷺ \nيقول المقداد: لما شرب رسول الله ﷺ اللبن وعرفت إنه خلاص ارتوى وبكده يبقى الدعوة إللي رسول الله ﷺ دعاها بقت من نصيبي قعدت أضحك لدرجة إني وقعت على الأرض من كثرة الضحك\nطبعا كل ده رسول الله ﷺ ميعرفش إللي حصل مع المقداد وصراعه من نفسه وإزاي إنه كان حزين جدا عشان خايف من دعوة رسول الله ﷺ عليه، وفجأة اتحولت الدعوة وبقت في مصلحته،\nفرسول الله ﷺ قال له:\nإحدى سَوْءاتك يا مقداد\nيعني إنت عملت عَملة يا مقداد\nفحكى له المقداد كل إللي حصل معاه، فقال له رسول الله ﷺ:\nدي رحمة من الله، مش كنت تقول عشان نصحي الاتنين النايمين دول عشان يشربوا معانا!\n☆شوفتم إزاي الشيطان ممكن يوقع الإنسان في الخطأ، ومش بس كده، ده بعد الخطأ يندمه وممكن يوصله لمرحلة اليأس من رحمة الله،\nيقول انت عملت المعصية الفلانية خلاص كده، ربنا مش هيقبلك تاني، ويزيّن له باقي المعاصي عشان يوقعه أكثر وأكثر وبالتالي يضيعه،\nكل واحد فينا يفتش في حياته، هنلاقي إننا ولو مرة واحدة على الأقل حصل معانا موقف زي ما حصل مع المقداد كده،\nالشيطان يزين لنا المعصية والخطأ، وبعد ما نقع في الخطأ الشيطان يندمنا ويحزننا،\nوده طبيعي وسنة كونية مستمرة؛ لأن دي شغلة الشيطان إللي أخذ العهد على نفسه إنه ينفذها لحد يوم القيامة\n لكن....لو احنا عملنا زي المقداد النتيجة هتكون مختلفة،\nالمقداد مستسلمش للشيطان واستمر في الخطأ،\nالمقداد عمِل عملا غطى به على خطأه، وانقلب حزنه لفرح،\nوأصابته دعوة رسول الله ﷺ بعد ما كان الشيطان مخوفه إن رسول الله ﷺ هيدعي عليه، \nوبكده نعرف إن كل الحاجات  إللي الشيطان بيخوفنا منها والصعوبات إللي بيقنعنا إنها موجودة عشان نتوقف عن العبادة ونسيب أوامر ربنا بحجة إننا مش هنقدر أو الموضوع صعب، ملهاش أي وجود،\nفمطلوب إننا نقاوم وسوسة الشيطان ونستعين بالله وهنلاقي إن كل إللي كنا خايفين منه كان مجرد وسوسة من الشيطان والموضوع أسهل وأبسط مما كنا نتخيل\nنيجي بقى نشوف مواقف لرسول الله ﷺ مع زوجاته\nزوجته سَودة بنت زمعة،\nقلنا قبل كده إن زوجها مات وسابها بين أهله المشركين، فتزوجها رسول الله ﷺ شفقة بها لأنها كانت مُسنة، \nالسيدة سودة مكنتش ذات جمال وكانت امرأة جسيمة يعني سمينة جسمها مليان، وكانت مَرِحة وروحها حلوة، دمها خفيف يعني رضي الله عنها فكانت بتغتنم أي فرصة عشان تضحك رسول الله ﷺ\nفي مرة كان رسول الله ﷺ بيصلي نافلة من النوافل،\nفدخلت سودة وراه تصلي خلفه فأطال رسول الله ﷺ في الصلاة،\nفبعد ما خلص صلاة قالت له سودة وهي بتضحك:\nأنا صليت خلفك يا رسول الله فلما ركعت وراك أمسكت أنفي مخافة أن يقطُر الدم،\nيعني وهي راكعة راحت مسكت مناخيرها عشان الدم مينزلش منه، فهي بتقوله بأسلوب ظريف: \nإنت طولت أوي يارسول الله لدرجة إن الدم كان هينزل من مناخيري فأنا لحقت نفسي وسديت مناخيري،\nفضحك رسول الله ﷺ من كلامها\nوكان زوجات رسول الله ﷺ بيحبوها وبيحبوا روحها المرحة دي و كانوا بيحبوا يهزروا معاها،\nفي مرة عائشة وحفصة رضي الله عنهما أوهموها إن الدجال خرج، فخافت وجريت استخبت في بيت كانوا بيولعوا فيه نار عشان يخبزوا فيه،\nفضحكت عائشة وحفصة من تصرفها، وجاء رسول الله ﷺ ولقاهم هم الاتنين بيضحكوا، فسألهم مالكم بتضحكوا على إيه؟\nفحكوا له إللي حصل مع سودة، فذهب إليها، فأول ما شافته ندهت عليه وسألته:\nالدجال خرج يا رسول الله\nفقال لها: لأ!\nفاطمأنت وخرجت من البيت وقعدت تنفض نفسها من خيوط العنكبوت\nوكانت عائشة رضي الله عنها بتحبها وبتقول إنها لم تتمنَّ إنها تكون زي حد في أسلوبه وطريقته وقوة نفسه إلا سودة رضي الله عنها،\nوحصل موقف بين عائشة رضي الله عنها وبين سودة ضَحك منه رسول الله ﷺ،\nفي يوم من الأيام، السيدة عائشة عملت أكلة اسمها الخَزِيرة، بتتعمل من الدقيق واللحم والمرقة، وكانت السيدة سودة بنت زمعة عندها في حجرتها جاءت تزورها،\nفجاءت عائشة رضي الله عنها بالخزيرة وقالت لسودة كُلي،\nفرفضت السيدة سودة وقالت مش عايزة، ملهاش نفس، وكان رسول الله ﷺ قاعد بينهم هم الاثنين واضع قدمه في حِجر عائشة، وقدمه الثانية في حِجر سَودة،\nفعائشة قالت لها:\n كُلي وإلا لطّخت وجهك بالخزيرة\nفرفضت سودة الأكل، فعائشة رضي الله عنها عاصت يدها بالخزيرة ولطّخت وجه سودة رضي الله عنها\nفضحك رسول الله ﷺ وشال رجله من حِجر سَودة وقال لها:\nقومي لطّخي وجهها زي ماهي لطّخت وجهك، \nفأخذت سَوْدة من القصعة إللي فيها الخزيرة، الطبق يعني ولطّخت وجه عائشة رضي الله عنها،\nورسول الله ﷺ بيضحك على منظرهم هم الاثنين\n♡رسول الله ﷺ كان أَليَن الناس وأكرمهم لأهل بيته زي ما عائشة رضي الله عنها بتوصفه:\nهو رجل زي باقي الرجال وبشر مثل باقي البشر، لكنه كان بيضحك ويبتسم وبيساعد أهل بيته،\nبيخيط ثوبه ويخدم نفسه ويكنس البيت، والبيت ده كان عبارة عن حجرة صغيرة ، \nيعني زوجته مش محتاجة مساعدة فيها، لكنه ﷺ بيوصل رسالة عملية لأهل بيته ولكل المسلمين إن زي ما الزوجين بيشتركوا في الحياة مع بعض، كذلك البيت ده حاجة مشتركة بينهم الجميع مسؤول عنه\nرسول الله ﷺ كان جعل لكل واحدة من زوجاته ليلة يذهب إليها ويبيت عندها، فالسيدة سَودة وهبت ليلتها للسيدة عائشة رضي الله عنها،\nلأنها ظنت إن رسول الله ﷺ كان هيطلقها، ورسول الله ﷺ لم يطلقها، وما كان رسول الله ﷺ يطلقها وهي كبيرة في السن وملهاش حد، \nده مش من أخلاق رسول الله ﷺ أبدا\nفهي إللي ظنت كده فقالت لرسول الله ﷺ إنها هتعطي ليلتها لعائشة عشان تفضل في عصمته في الدنيا وتكون زوجة له في الآخرة، وهي كانت عارفة أد إيه رسول الله ﷺ  بيحب عائشة رضي الله عنها، فأرادت إنها ترضي رسول الله ﷺ وتفرّحه بالهبة دي،\nوالكلام ده موجود في الحديث الصحيح،\nونزل فيها قول الله:\n\"وَإِنِ امْرَأَةٌ خَافَتْ مِن بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَا أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا \"\nأما الرواية إللي بتقول إن رسول الله ﷺ طلّق سودة بعد ما كبرت في السن وبعدين طلبت من رسول الله ﷺ إنه يرجعها لعصمته تاني في مقابل إنها تعطي ليلتها لعائشة فدي رواية ضعيفة لا تصح عن رسول الله ﷺ \nمن المواقف المضحكة إللي حصلت مع رسول الله ﷺ وعائشة رضي الله عنها،\nإن رسول الله ﷺ  في مرة دخل عليها وهي بتلعب بعرائس لها،\nفسألها رسول الله ﷺ: إيه ده؟\nفقالت له : دول بناتي\nفسألها، إيه إللي في وسطهم ده؟\nقالت له : فرس\nفسألها : وإيه إللي عليه ده ؟\nفقالت له: جناحان، فسألها باستغراب:\nفرس له جناجان؟!!!\nفقالت له:\nهو انت مسمعتش إن سليمان بن داود كان عنده فرس لها أجنحة\nفضحك رسول الله ﷺ من كلامها\n يعني متخيلين إن عائشة الصغيرة رضي الله عنها إللي اتولدت في الإسلام، هي إللي بتقول لرسول الله ﷺ إللي نزل عليه قصص الأنبياء كلهم إن سليمان عليه السلام كان عنده فرس لها أجنحة\nوكان رسول الله ﷺ بيسرّب لها بنات الأنصار عشان يلعبوا معاها، يعني يخليهم يروحوا لعائشة يلعبوا معاها من باب المؤانسة، \nوخصوصا إن عائشة رضي الله عنها كانت صغيرة في السن، هي أه كانت زوجة لكن محتاجة لأصحاب يؤنسوها وبتلعب بالعرايس عادي، زي ما تلاقي البنات في جامعة وبيحبوا الدباديب وبيلعبوا بيها\nفرسول الله ﷺ كان بيراعي مشاعر زوجاته وبيراعي حوائجهن النفسية، وهو القائل عن نفسه:\n\"خيركم خيركم لأهله وأنا خيركم لأهلي\"\nعارفين ليه رسول الله ﷺ بيقول خيركم خيركم لأهله\nلأن الإنسان ممكن يجامل الناس بصفة عامة ويظهر لهم أحسن حاجة فيه لما يقابلهم ساعة ولّا اتنين،\nلكن أهل بيته إللي عايشين معاه وعارفين كل حاجة عنه هم إللي يعرفوه كويس، وهنا يبان الشخص ده هل هو فعلا إنسان أخلاقه كويسة ولّا لأ\nفكل ما كان الإنسان بيعامل أهل بيته كويس زي ما بيعامل الناس برة وأكثر كمان كان فعلا على خُلق ودين،\nأما بقى لو بيعامل أهل بيته بطريقة سيئة ومش مراعي حقوقهم وفي نفس الوقت بيعامل الناس برة البيت أحسن من معاملته لأهله فده للأسف بيبص لمنظره قصاد الناس بس ومش فارق معاه هو عند ربنا إيه،\nلأن هو لو كان فيه خير، كان راعى حدود ربنا في أهل بيته الأول\nالكلام ده، للزوج والزوجة والأبناء ولكل واحد فينا، نراجع كده نفسنا ونشوف، أنا بعامل زوجي إزاي...بعامل زوجتي إزاي...بعامل أمي أبويا وإخوتي إزاي بغض النظر بقى هم يستاهلوا ولّا ميستاهلوش\nلأن احنا بنتعامل مع ربنا، مش بنتعامل مع الناس، ومفيش حاجة بتضيع عند ربنا، حتى مثقال الذر من الخير\nإن شاء الله المرة الجاية هنتكلم عن أحداث السنة الرابعة من الهجرة\n♡"}, {"n": 109, "l": "الجزء 83 | احداث السنه الرابعه من الهجره | اغتيال خالد الهذلي | حادثة ماء الرجيع", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_\n#الحلقة_الثالثة_والثمانون\n#أحداث_السنة_الرابعة_من_الهجرة\n#اغتيال_خالد_الهذلي\n#حادثة_ماء_الرّجيع\nاتكلمنا في الأجزاء الأخيرة إللي فاتت عن مصيبة المسلمين في أُحد وتعليق ربنا في القرآن على أحداث غزوة أحد،\nوشوفنا آثار غزوة أحد على المسلمين وعلى المشركين في مكة وعلى اليهود والمنافقين في المدينة،\nوشوفنا إزاي رسول الله ﷺ استطاع إنه يخرج بالصحابة من أزمتهم النفسية إللي حصلت لهم بسبب خطأ الرماة، وانتقل بهم لمرحلة الهجوم على جيش المشركين في غزوة حمراء الأسد،\nومن خلال غزوة حمراء الأسد استطاع رسول الله ﷺ إنه يسترجع شيء من هيبة الدولة الإسلامية،\nلكن صورة الدولة الإسلامية قصاد قبائل العرب اتهزت كتير جدا بعد ما كانت قبائل العرب بيعملوا للمسلمين حساب وخصوصا بعد غزوة بدر، \nففكروا إن المسلمين بقوا دلوقتي صيد سهل فبقوا مستنيين الفُرص عشان يهجموا على المسلمين\nخلونا نقسم كده أعداء المسلمين في المنطقة ونشوف وضعهم إيه:\n◇أولا :\nقريش العدو الأكبر للإسلام وإللي بتحاربه بقالها أكثر من أربعة عشر عام، وهي دلوقتي هدأت هدوء نسبي بعد انتصارها في أحد، وكانوا بعد غزوة أحد أعلنوا للمسلمين إنهم السنة الجاية هيتقابلوا في حرب تانية عشان يحددوا المنتصر منهم،\nيعني هم بينهم دلوقتي تعادل من وجهة نظر جيش المشركين، فطلبوا من رسول الله ﷺ إنهم يتقابلوا في بدر مرة ثانية عشان تبقى الحرب دي هي الفَيْصل بينهم،\nووافق رسول الله ﷺ على طلبهم، فغزوة أحد كانت في شوال من السنة الثالثة من الهجرة، \nوالميعاد إللي اتفق عليه المشركون والمسلمون كان في شوال من السنة الرابعة من الهجرة عند ماء بدر، فكده نقدر نقول إن المسلمين أَمِنوا جانب قريش لمدة سنة\n◇العدو الثاني من أعداء المسلمين هم : المنافقين بقيادة عبد الله بن أبي بن سلول، ودول بقوا ظاهرين للمسلمين وبقوا يعرفوهم من تصرفاتهم،\nطبعا كان في منافقين غير معروفين لا للمسلمين ولا حتى لرسول الله ﷺ زي ما ربنا قال له:\n\"وَمِمَّنْ حَوْلَكُمْ مِنَ الأَعْرَابِ مُنَافِقُونَ وَمِنْ أَهْلِ الْمَدِينَةِ مَرَدُوا عَلَى النِّفَاقِ لا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ\"\nوالمنافقين كانوا أشد السهام المُوَجهة إلى صدر الأمة الإسلامية بسبب إثارتهم للفتن والوقيعة بين المسلمين\n◇القسم الثالث كانوا اليهود إللي عايشين في المدينة، واحنا قلنا قبل كده إن يهود بني قينقاع خرجوا من المدينة، واتبقى داخل المدينة يهود بني قُرَيْظة، ويهود بني النُّضِير وفي بينهم وبين المسلمين عهد،\nلكن اليهود مشهورين بالغدر وكان رسول الله ﷺ بيتعامل معاهم بحذر،\nواحنا شوفنا إللي كعب بن الأشرف اليهودي عمله وبعدين تم قتله وهو من يهود بني النُّضير،\nوعلى الرغم من إن اليهود أكدوا على عهدهم مع رسول الله ﷺ بعد مقتل كعب بن الأشرف إلا إنهم ممكن يرجعوا في كلامهم وينتهزوا فرصة إصابة المسلمين في أحد وينقضوا العهد معاهم وينتقموا منهم \n◇أما القسم الرابع فهم:\nقبائل العرب إللي عايشين في البادية حول المدينة، والقبائل دي كانت عايشة على السّلْب والنّهب والأعمال الإجرامية، وقيام الدولة الإسلامية منعها من ثروات كثيرة كان ممكن تحصلها،\nفأكيد لما يسمعوا باللي حصل للمسلمين في أُحد مش هيضيعوا فرصة زي دي عشان يقضوا على دولة الإسلام،\nوفعلا ده إللي حصل\nقبيلة اسمها بني أسد بقيادة طُلَيْحة بن خُوَيْلد الأَسْدي بدأوا يجمعوا الناس للهجوم على المدينة، \nوصل الخبر لرسول الله ﷺ فجهّز سَرِية في شهر محرم من السنة الرابعة للهجرة بقيادة أبو سلمة رضي الله عنه وبعثه عشان يفرق القوة دي قبل ما يتجمعوا ويهجموا على المدينة،\nوفعلا اتفرق شمل بني أسد وحبطت محاولة الهجوم على المدينة،\nفي نفس الوقت ده وصل الخبر لرسول الله ﷺ إن واحد اسمه خالد بن سفيان الهُذَلي بيجمع بعض قبائل العرب عشان يهجموا على المدينة،\nوخالد بن سفيان ده من أعظم وأشرس المقاتلين العرب وكان رجل ضخم وعنده قدرات قيادية هائلة\nولو الرجل ده قدر إنه يروح للمدينة بالقبائل إللي جمعها هيبقى خطر كبير جدا على المسلمين\nعشان كده رسول الله ﷺ اهتم جدا بموضوع الرجل ده، وبدأ يشوف طريقة إزاي يتخلص منه، لأن هو الرأس المُدبّر، ولو خلصنا منه؛ تجمُّع القبائل هينتهي ومش هيقدروا يجمعوا نفسهم تاني\nأرسل رسول الله ﷺ لواحد من الصحابة اسمه عبد الله بن أُنَيس، وهو كان من حلفاء الأنصار وحضر بيعة العقبة الأولى والثانية وحضر غزوة أحد، \nفلما جاء لرسول الله ﷺ أخبره رسول الله ﷺ بقصة خالد بن سفيان الهذلي، وقال له رسول الله ﷺ إنه يروح ويقتل خالد بن سفيان،\nلكن المشكلة إن عبد الله بن أنيس ميعرفش شكل خالد بن سفيان ده، فإزاي هيقتل واحد ميعرفوش\nفطلب عبد الله بن أنيس من رسول الله ﷺ إنه يوصف له شكل خالد بن سفيان،\nمع إنه كان ممكن يأخذ الموضوع حجة عشان مينفذش أمر رسول الله ﷺ، وخصوصا إن المهمة خطيرة مش بسيطة،\nهيقتل رجل بالضخامة والقوة دي إزاي\nلكن أمر رسول الله ﷺ عند الصحابة ده كان حاجة كبيرة جدا، بينفذوا أوامره ولو على رقبتهم\nفقال له رسول الله ﷺ:\nأول ما هتشوفه هتحس في جسمك بقشعريرة..يعني لما تشوفه هتحس بالرعب\nفعبد الله بن أنيس استغرب، وقال له: \nبس أنا عمري ما خفت من حاجة أبدا يا رسول الله \nفقال له رسول الله ﷺ:\nعلامة بيني وبينك إنك لما هتشوفه هتخاف\nالمشكلة الثانية إللي قابلت عبد الله بن أنيس هي إزاي هيقتل خالد بن سفيان ده\nقائد زي كده أكيد هيكون حوله حراسة ومش هيكون لوحده، فإزاي هيوصل له أصلا\nفطلب عبد الله بن أنيس من رسول الله ﷺ إنه يأذن له بأنه يكذب عشان يقدر ينفذ مهمته، فأذن له رسول الله ﷺ بالكذب؛ لأن الصحابة كانوا عارفين إن الكذب كبيرة من الكبائر، \nلكن الكذب هنا في حالة الحرب وخداع الأعداء جائز، ورسول الله ﷺ الذي لا ينطق عن الهوى قال:\n\"الحرب خُدعة\" \nيعني الحرب الجيدة لصاحبها تكون في المُخادعة لا المواجهة، لأن المواجهة فيها خطر بعكس المخادعة، فاللي يقدر ينتصر بمخادعة أعدائه فده أحسن له من إنه ينتصر بالمواجهة إللي فيها مخاطر على نفسه وعلى الجيش إللي معاه،\nوهو ده إللي رسول الله ﷺ عمله وده كان من حكمته ﷺ \nفبدل ما يعرّض المدينة لخطر المواجهة وقتل المسلمين بدون داعي، اختار إنه يقضي على عدوه بالمخادعة عن طريق عبد الله بن أُنيس، \nفهو بكده بيقلل التضحيات المتوقعة لو جاء خالد بن سفيان بجيش لغزو المدينة \nواختار عبد الله بن أنيس بالذات لأنه أكثر واحد يصلح للمهمة دي، ورسول الله ﷺ بصفة عامة كان بيختار لكل واحد مهمته على حسب قدراته،\nعبد الله بن أنيس كان ثابت وقوي القلب مش بيخاف من حاجة، وكمان كان عنده ميزة وهي إنه عارف أماكن القبائل لأنها كانت بجوار مكان قبيلته قبيلة جُهَينة،\nخرج عبد الله بن أنيس من عند رسول الله ﷺ في سرية مكونة من رجل واحد فقط واتسمت السرية دي باسمه وهي سرية عبد الله بن أنيس،\nتوجه عبد الله لمكان قريب من المدينة اسمه نخلة مركز تجمع القبائل بقيادة خالد بن سفيان،\nوهو ماشي معاه سيفه، وصل لقرية شاف فيها رجل معاه بعض النساء بيختار لهن منزل فلما شاف الرجل حس بخوف ناحيته \nفعرف إن هو ده خالد بن سفيان الهُذلي وقال :\nصدق الله ورسوله\nوكان ساعتها وقت صلاة العصر، \nفخاف عبد الله بن أنيس إنه يقف يصلي فيشوفه خالد بن سفيان ويعرف إنه من أتباع محمد ﷺ،  \nوخاف إنه يأخر الصلاة لحد ما يخلص مهمته فتضيع عليه صلاة العصر، \nففكر في حل، فلقى الحل إنه يصلى وهو ماشي \nوكان في الركوع والسجود بيُومِئ برأسه، يعني بيوطي برأسه وهو ماشي،\n☆وسبحان الله، جاء الشرع بعدين بإقرار الطريقة دي في الصلاة، واتعرفت باسم صلاة الطالب وصلاة المطلوب،\nيعني الذي يطلب رجلا للقتل زي عبد الله بن أنيس كده،\nأو الذي يُطلب للقتل، \nيعني ناس عايزين يقتلوه ولو وقف هيلحقوه فيجوز إنه يصلي وهو ماشي زي عبد الله بن أنيس،\nحتى بدون قِبلة\nلما وصل عبد الله بن أنيس لخالد بن سفيان الهذلي سأل خالد عبد الله:\nانت مين\nفقال له عبد الله بن أنيس: أنا رجل من العرب، سمعت بك وبإنك بتجمع الناس عشان تغزو محمد، فجئت لك عشان أكون معاك\nفقال له خالد بن سفيان: أنا فعلا بعمل كده\nفمشي معاه عبد الله بن أنيس لحد ما بقى قريب منه ولما جاءت له الفرصة انقض عليه بالسيف وقتله ،\nوتركه ورجع لرسول الله ﷺ عشان يبشره، فلما دخل على رسول الله ﷺ قال له رسول الله ﷺ:\nأفلح وجهك ؟\nيعني نفذت المهمة؟\nفقال عبد الله بن أنيس: أفلح وجهك يا رسول الله،  قتلته\nفقام رسول الله ﷺ وجاء بعصا وأعطاها لعبد الله بن أنيس وقال له : هذه علامة بيني وبينك يوم القيامة \nيعني كأنه بيقول له انت لك مكانة عظيمة يوم القيامة وهتدخل جنة عرضها السماوات والأرض، \nوأخذ عبد الله بن أنيس العصا وكانت لا تفارقه وأوصى إنه لما يموت تُدفن معه في القبر\nوبكده استطاع رسول الله ﷺ إنه يثبت لأعدائه قوة المسلمين ويحفظ لدولة الإسلام هيبتها\nوفي وسط الأحداث دي كلها وانشغاله ﷺ بالتخطيط ومتابعة أخبار أعداء الإسلام، مكنش بيتأخر عن أصحابه ولا عن مساعدتهم،\nفاكرين جابر بن عبد الله بن حرام، إللي أبوه قُتل في غزوة أحد وهو إللي ربنا كلمه بدون حجاب\nجابر كان مهموم لأن أبوه قُتل وعليه دَيْن، لأن الشهيد حتى لو كان بيُغفر له كل ذنوبه ويُقضى عنه كل شيء لكن الدَّيْن لأ،\nيعني لو واحد قُتل شهيد ومصيره للجنة وعليه دَيْن،\nالدين ده يوقّفه عن دخول الجنة،\nفجابر عايز يقضي دين أبوه، لكن التمر إللي عنده في الحديقتين ميكفيش إنه يسد حتى دين واحد فقط، \nفهيعمل إيه بقى مع الباقيين\nودَيْنه ده كان ما يُعادل فوق المليون جنيه في زماننا دلوقتي\nفكان بيطلب من الناس إنهم يصبروا عليه شوية ومكنش حد بيصبر وكمان كانوا بيقولوا له كلام فاحش بيجرحه\nفذهب لرسول الله ﷺ وطلب منه إنه يأتي معاه عشان يستشفع بيه عند الدائنين دول وإنهم يصبروا عليه لحد الحصاد الجاي، يعني ياخدوا دلوقتي جزء والجزء التاني يأخذوه السنة الجاية،\nفجاء رسول الله ﷺ وكان معاه عمر بن الخطاب رضي الله عنه،\nفبدأ يكلمهم وكان فيهم واحد مصمم إنه ياخد من نوع معين من التمر ومياخدش من غيره، وكمان عايز نصيبه كله دلوقتي،\nإللي هو حاطط العقدة في المنشار\nفرسول الله ﷺ بدأ يكلمه عشان يصبر على جابر ويعطي له التمر إللي هو عايزه الحصاد الجاي، فرفض الرجل شفاعة رسول الله ﷺ وقال: لأ، أنا عايز حقي دلوقتي، لأن المال ده مال أيتام\nمع إنه كان ممكن يسأل رسول الله ﷺ عن الحكم الشرعي، لكنه رفض وصمم إنه يأخذ حقه،\nخدوا بالكم إن رسول الله ﷺ مش بيأمره زي ما أمر عبد الله بن أنيس، ده هو بس شفيع يعني له الاختيار إنه يقبل أو يرفض وإلا فلو كان أمره كان على طول هينفذ الأمر بدون نقاش\nفلما رسول الله ﷺ شاف الوضع كده قال لجابر : متزعلش، ودخل في الحديقة بتاعة جابر وبدأ يمشي فيها ويقف تحت كل نخلة ويتكلم بكلام لا يفهمه جابر،\nوبعد ما خلّص مشي قال لجابر إوزن لهم حقهم إللي عايزينه،\nوخرج رسول الله ﷺ يصلي العصر ومعاه عمر بن الخطاب رضي الله عنه،\nفقعد جابر يوزن للدائنين كل واحد نصيبه، فكلهم أخذوا حقوقهم كلها والتمر زي ما هو لم ينقص منه أي شيء\nفانطلق جابر بسرعة زي الشرارة لرسول الله ﷺ في المسجد وهو فرحان وقال له: شوفت يارسول الله، أنا وفيت دين عبد الله \nفقال: الحمد لله\nوده كان من معجزاته ﷺ \nفي شهر صفر من السنة الرابعة من الهجرة، جاء وفد لرسول الله ﷺ من قبيلتين عربيتين هما قبيلة عَضُل وقبيلة قارّة،\nقالوا لرسول الله ﷺ إن الإسلام بدأ يظهر فيهم بس هم ميعرفش حاجة عن تعاليم الإسلام،\nفطلبوا منه إنه يرسل معاهم بعض الصحابة عشان يعلموهم الإسلام والقرآن،\nفاختار رسول الله ﷺ عشرة من الصحابة كان منهم خُبَيْب بن عَدِي وزيد بن الدَّثِنّة وجعل قائدهم عاصم بن ثابت رضي الله عنه،\nخرج العشرة مع الوفد من المدينة متوجهين لمكان القبيلتين،\nوصل الخبر لقبيلة اسمها بنو الحارث من قريش،\nفأرسلت مئتي رامٍ على خيولهم، \nالرامي ده زي الطائرات المقاتلة دلوقتي في زماننا إللي بتبقى في طليعة الجيش، إللي بتفتتح القتال\nالمهم أرسلوا المئتين دول عشان يقتلوا العشرة، \nوفي نفس الوقت ده الوفد إللي كان مع المسلمين من القبيلتين أول ما وصلوا لمنطقة اسمها ماء الرّجِيع غدروا بالمسلمين،\nوطلبوا العون على المسلمين من حي من قبيلة هُذيل إللي كان لسه قائدهم خالد بن سفيان الهذلي مقتول مبقالوش شهر،\nفأجابوهم وحاوطوا الصحابة العشرة، وطلبوا منهم إنهم يستسلموا ولهم العهود إنهم مش هيقتلوا منهم أحد\n☆يعني همّ من البداية مكنوش عايزين إسلام ولا حاجة وكانوا عايزين ينتقموا من المسلمين،\nفهم كمان استخدموا الخديعة مع رسول الله ﷺ، وطبعا احنا عارفين إن رسول الله ﷺ بشر زينا بالضبط لا يعلم الغيب إلا إللي ربنا يُطلعه عليه،\nوهنا رسول الله ﷺ مكنش يعرف إللي هيحصل لأصحابه وإلا مكنش أخرجهم معاهم أصلا\n♡بس خدوا بالكم مش معنى كده إن رسول الله ﷺ استخدم نفس خديعة عضل والقارة لما أراد إنه يقتل خالد بن سفيان الهذلي إللي اتكلمنا عليه في البداية،\nفي فرق كبير جدا بين الموقفين، رسول الله ﷺ كان في حالة حرب مع خالد بن سفيان، فهو استخدم الخداع المشروع زي ما قلنا إن الحرب خدعة،\nوهو أصلا في حالة دفاع عن نفسه وعن المسلمين في المدينة، \nولو مكنش خالد بن سفيان ده بيجمع الناس عشان يهجموا على المدينة مكنش رسول الله ﷺ أرسل أحد لقتله لأن الإسلام لا يأمر بقتل الآمنين ولا أي أحد معاه عهد\nأما بقى وفد عضل والقارة فهم استخدموا الخداع الغير المشروع والمكر والغدر عشان يقتلوا المسلمين، \nيعني هم أعطوا الأمان لرسول الله ﷺ والصحابة وغدروا بيهم عشان ينتقموا منهم، مع إن المسلمين لم يؤذوهم في شيء\nفالموقف مختلف تماما بين رسول الله ﷺ وبين وفد عَضُل والقارة الغادر\nعاصم بن ثابت قائدهم إللي بعد إسلامه عاهد الله إنه لا يمس مشرك ولا يَمسه مشرك قال :\nوالله لا أنزل على عهد مشرك\nفقعد يقاتل مع العشرة حتى قُتل هو وستة من أصحابه، فتبقى ثلاثة : خُبيب بن عدي وزيد بن الدثنة وصحابي ثالث لم يعرف الرواة اسمه،\nفأمسك المشركون الثلاثة من الصحابة وكتفوهم فقال الثالث : والله هذا أول الغدر\nوقعد يقاومهم ويقاتلهم وهم يجروه لحد ما قُتل مع أصحابه السبعة، وتبقى خُبيب بن عدي وزَيد بن الدَّثِنة.\nياترى هيحصل معاهم إيه، ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 110, "l": "الجزء 84 | أحداث السنه الرابعه من الهجره | باقي حادثة ماء الرجيع | قصة مقتل عاصم و مرثد وخبيب وزيد", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الرابعة_والثمانون\n#أحداث_السنة_الرابعة_من_الهجرة\n#باقي_حادثة_ماء_الرجيع \n#قصة_مقتل_عاصم_ومرثد_وخبيب_وزيد\nوقفنا المرة إللي فاتت عند مقتل ثمانية من الصحابة عند ماء الرّجيع بسبب غدر وفد قبيلتي عَضُل والقارة واتبقى اثنين من الصحابة هما خُبَيْب بن عدي وزيد بن الدّثِنّة،\nكان من الصحابة الثمانية إللي قتلوا واحد اسمه مرثد بن أبي مرثد،\nوالصحابي ده له قصة\n☆لكن قبل ما نعرف قصته في نقطة قلتها الجزء إللي فات عايز أوضحها عشان حسيت إنها ممكن تتفهم غلط\nأنا قلت عن عضل والقارة إنهم 《استخدموا الخديعة هم كمان مع رسول الله ﷺ》\nفكده يتفهم إن رسول الله ﷺ استخدم نفس خديعة عضل والقارة لما أراد إنه يقتل خالد بن سفيان الهذلي إللي اتكلمنا عليه في بداية الجزء إللي فات،\nلكن طبعا في فرق كبير جدا بين الموقفين، رسول الله ﷺ كان في حالة حرب مع خالد بن سفيان، فهو استخدم الخداع المشروع زي ما قلنا إن الحرب خدعة،\nوهو أصلا في حالة دفاع عن نفسه وعن المسلمين في المدينة، ولو مكنش خالد بن سفيان ده بيجمع الناس عشان يهجموا على المدينة مكنش رسول الله ﷺ أرسل أحد لقتله لأن الإسلام لا يأمر بقتل الآمنين ولا أي أحد معاه عهد\nأما بقى وفد عضل والقارة فهم استخدموا الخداع الغير المشروع والمكر والغدر عشان يقتلوا المسلمين، \nيعني هم أعطوا الأمان لرسول الله ﷺ والصحابة وغدروا بيهم عشان ينتقموا منهم، مع إن المسلمين لم يؤذوهم في شيء\nفالموقف مختلف تماما بين رسول الله ﷺ وبين وفد عَضُل والقارة الغادر\n◇أتمنى إن النقطة دي تكون وضحت، وأنا هعمل للجزء إللي فات تعديل إن شاء الله وأضيف له النقطة دي، بس حبيت أوضح للناس إللي قرأت الجزء إللي فات خلاص\nنرجع لقصة مَرْثد بن أبي مرثد، مرثد ده كان قبل الإسلام بيحب واحدة اسمها عَناق وكانت امرأة بغي يعني بتشتغل زانية، تأخذ مال مقابل الزنا، وكانت من أجمل نساء قريش، وهو كان بيحبها وعلى علاقة بها وهي كمان كانت بتحبه، \nفأسلم مرثد رضي الله، وقال :\nوالله لأكفرّن عن كل إللي كنت بعمله قبل الإسلام\nمع إن الإسلام يمسح كل الذنوب والمعاصي إللي كانت قبله، لكن من صدقه رضي الله عنه كان عايز يرضي ربنا بأيّ طريقة،\nهاجر مرثد مع أبوه وعاش في المدينة، واحنا عارفين إن مش كل المسلمين استطاعوا الهجرة وفي صحابة منعهم أهلهم من الهجرة وبيُعذبوا في مكة،\nتخيلوا إن مرثد كان بييجي من المدينة لمكة على رجله ويدخل مكة مُتسلل في الخفاء من غير ما حد يحس بيه وياخد واحد واحد من المسلمين، \nيشيله على ظهره وياخده ويهربه للمدينة مشي\nوالمسافة بين مكة والمدينة خمسمائة كيلو، يعني مسافة مش بسيطة خالص\nواستمر يعمل كده، ياخد واحد من المسلمين المستضعفين من مكة للمدينة وبعدين يرجع تاني لمكة وهكذا،\nفي يوم من الأيام وهو متسلل لداخل مكة في الليل في ضوء القمر لمحته عَناق فندهت عليه : مرثد\nفسمع صوتها وعرف إنها عناق فطلع يجري واستخبى في زاوية، طبعا الشيطان مسابهوش\nجاله يوسوس له ويذكره بحبه وأوقاته مع عناق، ماهو الصحابة بشر زينا، يوسوس لهم الشيطان ويذكرهم بأخطائهم ويزين لهم المعصية عشان يقعوا فيها تاني\nتخيلوا بقى الوساوس في دماغه وعناق قعدت تقرب وهي بتنادي عليه:\nمرثد..مرثد..وهو مبيردش عليها خالص، فلما قربت منه جدا قال لها : ابعدي عني يا عناق\nفقالت له : مرثد! تعال نام عندي في بيتي الليلة.\n《تدعوه للزنا》\nتخيلوا الفتنة والابتلاء إللي متعرض له مرثد في اللحظة دي،\nنفسه والهوى والشيطان وامرأة يحبها وهي تحبه، كل ده بيضغط عليه،\nفقال لها : يا عناق، أنا أسلمت والإسلام يُحرم الزنا\n《الإسلام حرم الزنا من البداية في مكة》\nفقالت له : تعال نام عندي الليلة وإلا صرخت ولميت عليك الناس فيأخذوك ويعذبوك\nفقال لها: يا عناق! إن رجلا يبيع جنة عرضها السماوات والأرض بلذة ساعة معاكِ لمجنون\n☆إن امرأة تبيع جنة عرضها السماوات والأرض عشان كم شعرة تشيلها من حواجبها لمجنونة،\n《لعن الله النامصة والمتنمصة》\n إن امرأة تبيع جنة عرضها السماوات والأرض عشان شوية ملابس ضيقة تظهر مفاتنها للناس في الشارع لمجنونة،\n《صنفان من أهل النار منهما: نساء كاسيات عاريات مائلات مُمِيلات لا يدخلن الجنة ولا يجدن ريحها》\nإن رجلا يبيع جنة عرضها السماوات والأرض بترك الصلاة لمجنون،\n《العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر》\nأي إنسان يبيع جنة عرضها السماوات والأرض من أجل أي شيء مهما كان فهو مجنون كما قال مرثد رضي الله عنه\nطبعا لأن عناق مشركة ومش فاهمة يعني إيه جنة عرضها السماوات والأرض دي، وإزاي الجنة دي أهم من حبها له وحبه لها راحت مصرخة عشان الناس تتجمع،\nمرثد مستناش طلع يجري في اتجاه المدينة والناس وراه،\nفضل يجري لحد ما وصل للمدينة وهو كان قوي جدا رضي الله عنه،\nلدرجة إن رسول الله ﷺ في غزوة بدر كان بيخليه يشيل الأسرى من قوته \nالمهم وصل مرثد للمدينة وأول ما دخل المدينة راح لرسول الله ﷺ في المسجد وسلم عليه وأول كلمة قالها لرسول الله ﷺ:\nيا رسول الله ينفع أتزوج عناق\nيعني هو لسه بيحبها ويريدها، لكن إللي منعه هو تقوى الله وحرمة الزنا، فهو دلوقتي يريدها بالحلال، فجاء لرسول الله ﷺ وطلب إنه يتزوجها،\nرسول الله ﷺ لم يرد عليه، لأن الموضوع مش بإيده، هو ميقدرش يتكلم ولا يقول أه أو لأ إلا بوحي من الله،\nفنزل جبريل عليه السلام بالوحي وقال لرسول الله ﷺ قل لمرثد:\n\"وَالزَّانِيَةُ لَا يَنْكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَلِكَ عَلَى الْمُؤْمِنِينَ\"\nتخيلوا وقع الصدمة على مرثد، وإنه ميقدرش حتى يتزوجها\nهل اعترض وقال: طيب أنا اعمل إيه دلوقتي، ولّا خلاص أروح أزني بيها بقى وبعدين ابقى اتوب،\nولا قال ده إيه الدين المتشدد ده، ولا فين من ترك شيئا لله عوضه الله خيرا منه،\nأنا تركتها في الحرام أهه مش المفروض ربنا يكافئني بالحلال، ولا...ولا...من الحاجات إللي بنسمعها من الناس ومش عاجبهم الدين وعايزين دين متفصل على هواهم\nمرثد كان من أصحاب الإيمان الراسخ،\nمكنش من الناس إللي بتعبد الله على حرف فلما يجيله الخير يبقى الدين بالنسبة له حلو وجميل،\nولما يشوف البلاء والصعاب يبقى الدين ده تشدد ووحش وخلاص مش عايزينه،\nمرثد سلّم لأمر الله ولم يعترض ورضي بجنة عرضها السماوات والأرض إللي فيها الحور العين إللي لو واحدة منهم بس بصت على الدنيا لغطى بياض وجهها على ضوء الشمس،\nوحتى لو كانت عناق من أجمل نساء قريش تيجي إيه هي  جنب واحدة من الحور العين \nوأهه قُتل شهيدا رضي الله عنه ودخل جنة عرضها السماوات والأرض وله اثنين وسبعين زوجة من الحور العين\n☆طبعا السؤال هنا، ليه ربنا لم يُرد إن مرثد يتزوج عناق، ماهو فعلا عايزها في الحلال أهه\nالمؤمن الصالح لا يتزوج الزانية التي اعتادت على الزنا، لأن المرأة ساعتها هيتكوّن عندها أخلاق تناسب أحوال الزناة، \nفلا يرغب في معاشرة الزانية إلا إللي تعجبه الأخلاق دي، وخصوصا إن مرثد كان معتاد للزنا زي عناق قبل الإسلام،\nففي الوقت ده كان لسه المسلمون قريبين من عهد الشرك والجاهلية،\n فكان من حكمة ربنا في تشريع الإسلام إنه يبعد المسلمين عن كل حاجة ممكن تفكرهم باللي كانوا متعودين عليه قبل الإسلام،\nلأنه كان يريد إن أخلاق الإسلام تبقى طبيعة فيهم ويبعدهم عن أي حاجة ممكن تجدد فيهم أخلاق كانو خلاص قربوا ينسوها،\nوالحكم ده هيتنسخ بعدين لما تنزل آية:\n\"وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ \"\nفالزانية دخلت في الأَيامى، فبعد استقرار الإسلام ومبقاش في خوف إن أخلاق الجاهلية ممكن ترجع للمسلمين تاني نزل نسخ الآية الأولى\nوالنسخ يعني إن الآية أو الحديث إللي فيها حكم شرعي جديد تمسح الآية أو الحديث إللي فيهم الحكم الشرعي القديم.\n《طبعا الموضوع فيه تفصيل كبير واختلاف بين العلماء، أنا جبت لكم المختصر المفيد، إللي عايز يتوسع في المسألة ويعرف أقوال العلماء هيلاقي رابط للإسلام سؤال وجواب فيه الشرح》\nنرجع للأحداث \nعاصم بن ثابت قائد العشرة حصلت معاه قصة عجيبة بعد موته\nاحنا عارفين إن عاصم بعد ما أسلم عاهد الله إنه لا يمس مشرك ولا يمسه مشرك،\nوسبحان الله، فعلا فضل محافظ على العهد ده طول حياته ولم يمس مشرك ولم يسمح لمشرك أن يمسه،\nفلما عرف إنه خلاص مقتول قال:\nاللهم إني حميت دينك أول النهار فاحمِ لي لحمي آخره\nفلما قُتل رضي الله عنه المشركين عايزين يقطعوا رأسه ويأخذوه هو بالذات، عارفين ليه\nفاكرين في غزوة أحد المرأة إللي كان اسمها سُلافَة لما كانت بتشوف راية المشركين كل شوية تقع وتترفع فعرفت إن حامل الراية بيُقتل فتوجهت ناحية الراية فوصلت مع قتل عاصم لاثنين من حملة الراية وكان الاثنان هم أولادها،\nفصرخت وقالت:\nمن يأتيني برأس عاصم أشرب في جمجمته الخمر وأعطيه وزنها ذهبا لمن يأتيني به؟\nأهه المشركين لسه فاكرين وعد سُلافة، فعايزين رأس عاصم عشان يأخذوا المكافأة،\nلما حاولوا يأخذوا رأس عاصم لقوا سِرب من الدبابير يعني مجموعة كبيرة من الدبابير غطت جسم عاصم كله ومخلتش حد يقرب منه\nفقالوا نستنى لليل والدبابير هترجع لأعشاشها،\nفلما جاء الليل لقوا سِيل من الماء جاء وحمل جثة عاصم معاه ومعرفوش يوصلوا لجثته نهائي\nفربنا أكرمه بالشهادة لكنه حماه من هَتك حُرمته بقطع جسده،\nوالجزاء من جنس العمل، ربنا بيحفظ عبده المؤمن سواء في حياته أو بعد مماته\nاتبقى عندنا خُبيْب بن عدي وزيد بن الدّثنة، المشركين أخذوهم وباعوهم لمشركي مكة، بنو الحارث اشتروا خبيب بن عدي عشان يقتلوه ثأرا لزعيمهم الحارث إللي قتله خبيب بن عدي في غزوة بدر،\nأما زيد بن الدَّثِنّة فاشتراه صفوان بن أمية عشان يقتله ثأرا وانتقاما لأبيه أمية بن خلف إللي قُتل في غزوة بدر،\nبنو الحارث حبسوا خبيب لحد ما يخرجوا من مكة ويقتلوه، عشان مينفعش يقتلوه في البلد الحرام،\nفلما كان في الأسر طلب موس عشان يستحد به، يعني يحلق شعر الإبط والعانة،\nلأن رسول الله ﷺ قال إن شعر الإبط والعانة لا يُترك أكثر من أربعين يوم،\nفهو على الرغم من إللي هو فيه وإنه خلاص هيُقتل إلا إنه كان حريص على طاعة أمر رسول الله ﷺ \nكان في امرأة زي ما بنقول سجّانة، كانت بتجيب له الأكل في المكان المحبوس فيه، وكان عندها طفل صغير،\nففي يوم وهي قاعدة مع ابنها من التعب غَفَت، يعني راحت في النوم، والولد نزل من على رجلها يحبو، يعني يزحف لحد ما وصل عند خبيب،\nفشافه خبيب وشاله وحطه على رجله،\nوكان الموس ساعتها في إيده، فانتبهت الأم وفتحت عينها ملقتش ابنها، دوّرت عليه لقت الولد قاعد على رجل خبيب وماسكه بإيد وإيده التانية ماسك الموس،\nراحت شهقت \nطبعا خافت على ابنها، واحد كده كده مقتول فإيه المانع يعني لما ياخد في سكته واحد ولا اتنين عشان ينتقم منهم وهم أصلا هيقتلوه ظلما وعدوان\nفلما شافها شهقت، قال لها: انتِ خايفة إني أقتله، والله لا أقتله، وترك الطفل يروح لأمه،\nخُبيب كان عارف كويس جدا إن كل مسلم هو سفير للإسلام يعكس صورته الحسنة عن طريق أخلاقه ومعاملاته الطيبة،\nوده خلى المرأة تقول عنه: والله ما شفت أسيرا خير من خبيب\nوحكت عنه إنها شافته في يوم بياكل عنقود من العنب وهو مُقيد بالحديد ومفيش في مكة كلها حبة عنب\nفدي كانت كرامة من كرامات الله لخبيب رضي الله عنه،\nخرج المشركون بخبيب لمنطقة اسمها التنعيم برة الحرم عشان يقتلوه هناك،\nوقبل ما يقتلوه قال لهم سيبوني أصلي ركعتين فتركوه، يعني آخر طلب له في الحياة،\nفصلى ركعتين خفيفتين وقال لهم: \nلولا إنكم ممكن تظنوا إني خايف من القتل كنت طولت في الصلاة\nفكان خبيب هو أول من سن لمن يُقتل صبرا أن يصلي ركعتين\n◇طبعا رسول الله ﷺ لما عرف أقر الركعتين دول ولو كان فعله خطأ كان رسول الله ﷺ نبه وقال إللي فعله خبيب خطأ،\nيعني مش أي حد يخترع حاجة في الدين نمشي وراه،\nلازم يكون في دليل من القرآن او السنة\n☆فاكرين بقى معنى قتل الصبر\nمعنى يُقتل صبرا إن الإنسان يُقتل في غير معركة أو حادثة، \nيعني نجيب شخص كده ونكتفه ونقتله، سواء بالذبح أو ضرب النار أو بالسهام أو ...أو...\nوقتل الصبر للمسلم له أجر عظيم يقول رسول الله ﷺ:\n\"قَتْلُ الصَّبْرِ لا يَمُرُّ بِذَنْبٍ إِلا مَحَاهُ \" \nبعد ما صلى خبيب دعا على كل الموجودين:\nاللهم احصهم عددا ..واقتلهم بددا ..ولا تبقي منهم أحدا\nوكان أبو سفيان حاضر ومعاه ابنه معاوية،\nفلما بدأ خبيب يدعو راح أبو سفيان رامي معاوية على الأرض وجعل وجهه للأرض حتى لا تصيبه دعوة خبيب،\nهم كان عندهم اعتقاد إن المدعو عليه لو نزل في الأرض وألصق نفسه بها لم تصبه الدعوة،\nوصلبه المشركون على خشبة عشان يقتلوه وكان أول مسلم يُصلب،\nوأنشد خبيب شعر قبل قتله مباشرة، واشتهر منه :\nولستُ أبالي حين أُقتل مُسلما  \n على أيّ جنبٍ كان في الله مَصْرعي\nيعني مادام أنا هموت على الإسلام مش مهم بقى إيه الطريقة إللي هموت بيها أو المكان إللي هموت فيه\nوقال : يارب مش لاقي حد يبلغ رسولك مني السلام فبلغه مني السلام!\nفقام عقبة بن الحارث إلى خبيب وقتله وهو مصلوب\nأما الصحابي الثاني زيد بن الدّثنة إللي اشتراه صفوان بن أمية، أمر صفوان موْلى له اسمه نِسْطاس إنه يقتل زيد وكان ده في نفس اليوم إللي قُتل فيه خبيب،\nلما أرادوا إنهم يقتلوا زيد جاء أبو سفيان وسأله وحلّفه بالله قال:\nناشدتك الله يازيد! تحب إنك تكون بين أهلك وأحبابك ومحمد عندنا هنا نضرب عنقه مكانك؟\nفقال زيد بن الدثنة الأنصاري إللي لم يعش مع رسول الله ﷺ غير ثلاث سنوات فقط :\nوالله ما أحب إني أكون بين أهلي وأحبابي ومحمد في المكان إللي هو فيه تصيبه شوكة \nفقال أبو سفيان:\nأنا مشفتش حد من الناس بيحب حد زي حب أصحاب محمد لمحمد\nوقُتل رضي الله عنه وبكده يكتمل قتل العشرة من الصحابة، \nهم أه قُتلوا وممكن نحس بالألم عشانهم، لكن هم في قبورهم مرتاحين، في أحسن حال، مُنعّمين في قبورهم\nإزاي وصل الخبر لرسول الله ﷺ \nفي نفس اليوم إللي حصل فيه الغدر وعرف الصحابة إنهم مقتولين دعا عاصم بن ثابت رضي الله عنه وقال:\nاللهم بلغ عنا نبيك\nفاستجاب الله لعاصم وأخبر رسول الله ﷺ باللي حصل مع الصحابة العشرة في نفس اليوم\nطبعا رسول الله ﷺ حزن لمقتل أصحابه، كل واحد فيهم له معاه قصة، وهو بشر يحزن لما بيفقد حد بيحبه،\nأيوة بيهون عليه لما يعرف إنهم في الجنة لكن حزن الفقد موجود وخصوصا لما يكونوا من المقاتلين الأشداء ومن المدافعين عن الإسلام\nللأسف حصلت في نفس الشهر حادثة هي أشد من حادثة مقتل العشرة، أدت لحزن رسول الله ﷺ حزن شديد جدا،\nإيه هي الحادثة دي وإيه إللي حصل فيها،\nده إللي هنعرفه الجزء الجاي بعد بكرة إن شاء الله\n☆"}, {"n": 111, "l": "الجزء 85 | أحداث السنه الرابعه من الهجره | حادثة بئر معونه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة_والثمانون\n#أحداث_السنة_الرابعة_من_الهجرة\n#حادثة_بئر_معونة\nاتكلمنا المرة إللي فاتت عن حادثة ماء الرجيع إللي مات فيها عشرة من أصحاب رسول الله ﷺ، وكانت الحادثة دي في شهر صفر من السنة الرابعة من الهجرة،\nفي نفس شهر صفر جاء لرسول الله ﷺ  في المدينة رجل من الناس المشهورين في العرب وهو أبو البراء عامر بن مالك العامري،\n كان بيُضرب به المثل في الشجاعة وكان يُلقب بمُلاعِب الأَسِنّة، وهو عم الشاعر الجاهلي المعروف إللي أسلم بعدين لبيد بن ربيعة صاحب المُعَلّقة،\nوكان لما يركب على الفرس رجله تصل للأرض فتخيلوا الرجل ده كان ضخم أد إيه\nالمهم الرجل ده جاء لرسول الله ﷺ في المدينة وعرض رسول الله ﷺ عليه الإسلام فلم يُسلم عامر بن مالك وفي نفس الوقت مرفضش الإسلام وقال لرسول الله ﷺ:\nأرسل معي مجموعة من أصحابك يدعوا قومي فلو أسلم قومي أسلمت معهم\nوكان عامر بن مالك من أهل نجد،\nفقال له رسول الله ﷺ: إني أخاف عليهم من فُجّار أهل نَجْد ليقتلوهم!\nيعني رسول الله ﷺ خايف على أصحابه من إن ناس من قطاع الطرق الفَجرة يجتمعوا على أصحابه فيقتلوهم،\nفقال له عامر بن مالك:\nأنا أُجيرُهم، فأرسلهم لأهل نجد يدعوهم للإسلام\nيعني هم هيكونوا في جواري، يعني في حمايتي،\nواحنا اتكلمنا قبل كده عن معنى الجوار وأهميته ومكانته عند العرب وإزاي إنهم كانوا بيحترموا قانون الإجارة ده،\nفلأن رسول الله ﷺ عارف احترام العرب لقانون الإِجارة   وخصوصا لو كانت الإجارة جاية من واحد زي مُلاعب الأسنة الشجاع المشهور،\nوافق إنه يرسل معاه مجموعة من الصحابة معظمهم من القُرّاء، وكانت المجموعة دي عددهم سبعين رجل من الصحابة والقراء يعني حفظة القرآن إللي كانوا عارفين أسباب النزول وكانوا من خيار المسلمين.\n☆ومعنى حفظة القرآن يعني كانوا حافظين كل القرآن إللي نزل ساعتها مش القرآن إللي هو الثلاثين جزء؛ لأن مش كل القرآن كان نزل في الوقت ده\nكان في السبعين دول المُنذر بن عمرو إللي شهد بيعة العقبة الثانية وحضر غزوة بدر وأُحد مع رسول الله ﷺ،\nوكان فيهم حرام بن مِلحان أخو أم سُليم صاحبة أغلى مهر في الإسلام إللي اتكلمنا عنها في الجزء الخامس والستين،\nوكان فيهم عامر بن فُهيرة مولى أبي بكر الصديق إللي كان له دور في يوم هجرة رسول الله ﷺ،\nكان بيأخذ أغنام أبي بكر يمشي بها كأنه خارج لرعيها،\nفيمشي بها على أثار أقدام عبد الله بن أبي بكر إللي كان بيروح لرسول الله ﷺ وأبو بكر الصديق في الغار وينقل لهم أخبار أهل مكة لو تفتكروا\nوكان من السبعين دول الحارث بن الصُّمَّة إللي كان من الناس إللي ثبتت مع رسول الله ﷺ في غزوة أحد بعد ما الناس انكشفوا عنه وكان بيدافع عنه،\nوكان من السبعين كذلك عمرو بن أمية الضمري إللي أسلم بعد غزوة أحد وكان خروجه مع مجموعة الصحابة دول هو أول مشهد يَشهده بعد إسلامه\nخرج السبعون صحابي بكتاب من رسول الله ﷺ متوجهين لديار نجد عشان يدعوهم للإسلام، \nوكان حامل رسالة رسول الله ﷺ هو الصحابي حرام بن مِلْحان رضي الله عنه،\nوصلوا لمكان اسمه بئر مَعُونة، سمع بيهم واحد اسمه عامر بن الطُّفَيْل، وعامر بن الطفيل ده يبقى ابن أخ عامر بن مالك مُلاعب الأسنة إللي راح لرسول الله ﷺ وطلب منه إرسال الصحابة لقبيلته، \nلكن عامر بن الطفيل كان من الفَجرة الفُسّاق الذين لا يُراعون قوانين ولا أعراف، \nفاستعدى على المسلمين قومه بني عامر بن صَعْصَعة، يعني طلب منهم وحمّسهم إنهم يساعدوه في الهجوم على المسلمين وقتلهم، \nلكنهم رفضوا طبعا لأن عامر بن مالك مُلاعب الأسنة سيدهم أعطى للمسلمين الجوار، فهم احترموا قرار سيدهم،\nوحتى عامر بن مالك خرج لابن أخيه عامر الطفيل وقال له:\nوفد المسلمين ده في جواري ملكش دعوة بيهم\nفعامر بن الطفيل قال لعمه عامر بن مالك : \nملكش عندنا جوار\nيعني مش هحترم جوارك وجوارك وحمايتك دي ملهاش أي قيمة عندي،\nفلما لقى عامر بن الطفيل قومه رافضين يساعدوه استعان بقبائل تانية من نَجد هم رَعْل وذَكْوَان وعُصِيّة فاستجابوا له وخرجوا معاه عشان يقتلوا المسلمين،\nوصلوا للصحابة عند بئر مَعُونة وحاصروهم وبدأوا يقتلوهم\nهم دافعوا عن نفسهم لكن سبعين في مقابل قبائل كثيرة هيعملوا إيه،\nحرام بن ملحان حامل رسالة رسول الله ﷺ حاول إنه يكلمهم عن رسول الله ﷺ ويدعوهم للإسلام ويعطيهم رسالة رسول الله ﷺ لكن عامر بن الطفيل حتى لم يفتح الرسالة وأشار لواحد من إللي معاه إنه يقتل حرام بن ملحان من الخلف،\nمع إن حرام بن ملحان رسول ومعروف عند كل الناس سواء العرب أو غيرهم إن الرسل لا تُقتَل،\nيعني مينفعش واحد بيوصل لك رسالة إنك تقتله، هو فقط حامل رسالة فملوش ذنب، ودي كانت كبيرة جدا عند العرب زمان،\nلكن عامر بن الطفيل أصلا مش بيعترف بالقوانين وكان فاجر  وطاغية\nقام الرجل وجاء من وراء حرام بن ملحان وطعنه في ظهره من الخلف بالرمح وخرج الرمح من بطنه\nبكل تلقائية أخذ حرام بن ملحان بيده الدم إللي اتفجر من جسمه ومسح به وجهه وهو يقول : فزتُ ورب الكعبة\nطبعا الرجل إللي طعنه اتصدم\nأطعنه وأقتله وأحرمه من الحياة ومتعتها وتحقيق أحلامه ويقول فزت\nوالإنسان لا يكذب عند الموت، وحتى لو كذب في بعض الأوقات لكن عند الموت مفيش كذب،\nفمعنى إنه قال فاز فهو صادق ،فإيه بقى الفوز إللي بيتكلم عنه ده\nطبعا هو كان مشرك فمكنش يعرف إن في عالم تاني والعالم ده فيه نعيم أبدي وملذات لا تخطر على قلب بشر،\nميعرفش إن :\n\"فَمَن زُحْزِحَ عَنِ النَّارِ وَأُدْخِلَ الْجَنَّةَ فَقَدْ فَازَ\"\nمحتاجين نرسخ جوانا إن الفوز الحقيقي فعلا هو الفوز بالجنة، مش الفوز بأي شيء في الدنيا ولو كان على حساب الدين، \nمهما عشنا في الدنيا وحققنا كل أحلامنا، في النهاية هنسيب كل حاجة ونمشي، ونروح بعدها للمكان إللي هنعيش فيه للأبد،\nفكل واحد يشتغل لتحقيق حلمه الأبدي إللي لن يتركه أبدا وهو الجنة\nتخيلوا بقى إن الكلمة إللي قالها حرام بن مِلحان دي كانت سبب في إن الرجل المشرك ده يروح يسأل المسلمين عن جملة 《فزت ورب الكعبة》 \nولما المسلمون أخبروه بإن حرام بن ملحان فاز بالشهادة وشرحوا له يعني إيه إيمان بالله وإن في حاجة اسمها جنة وفيها درجات للشهداء،\nالرجل المشرك إللي كان اسمه جبار بن سُلْمى دخل في الإسلام\nوكان كل إللي يعرف إنه أسلم كان يستغرب من إسلامه ويسألوه عن السبب فيحكي لهم عن قصته مع حرام بن ملحان.\n☆كلمة واحدة بس قالها حرام بن ملحان عند موته كانت سبب في إسلام قاتله، وهو مكنش يعرف إن الكلمة دي هتكون سبب في إسلام واحد من المشركين ويبقى إسلامه في ميزان حسناته بعد موته\nمحدش يستهين بكلمة يقولها يدعو بها إلى الله حتى ولو كانت بسيطة، \nمحدش يعرف امتى ربنا هيفتح قلوب الناس، احنا بس علينا نوصل لهم أي حاجة نعرفها عن ربنا وملناش دعوة بالنتيجة بعد كده\nقَتل المشركون الصحابة السبعين كلهم إلا ثلاثة، اثنين كان ربنا قدر إنهم يتأخروا عن المجموعة هما عمرو بن أمية الضَّمْري والحارث بن الصُّمّة، \nلما قربوا من مكان أصحابهم شافوا إن في طيور بتطير فوق المكان بتاع أصحابهم،\nفقالا : أصحابنا حصل لهم حاجة \nفلما وصلوا لقوا الصحابة كلهم مقتولين، ما عدا واحد ظنوه إنه قُتل ولكن كان لسه فيه نفس وعاش حتى شهد غزوة الخندق وقُتل فيها شهيدا رضي الله عنه،\nالمشركين شافوا الحارث وعمرو بن أمية فقال الحارث لعمرو بن أمية: إيه رأيك \nفقال عمرو بن أمية:\nرأيي إننا نرجع لرسول الله ﷺ ونخبره باللي حصل لأصحابنا\nفقال له الحارث :\nما كنت لأتأخر عن موطن قُتل فيه المنذر بن عمرو\nيعني هو من حبه للمنذر بن عمرو صاحبه كان يتمنى إنه يقتل معاه في نفس المكان،\nفقاتل الحارث المشركين حتى قُتل، أما عمرو بن أمية فأسره المشركون، فأطلقه عامر بن الطفيل لأن أمه كان عليها عتق رقبة، فأعتقه عشان يوفي كفارة أمه،\nعامر بن مالك ملاعب الأسنة لما الناس محترمتش جواره أصابه الهم والغم وعكف على شرب الخمر لحد ما قتله شرب الخمر\nرجع عمرو بن أمية الضمري لرسول الله ﷺ في المدينة عشان يخبره باللي حصل،\nلكن رسول الله ﷺ كان أصلا عرف من الوحي لأن الصحابة إللي اتغدر بيهم قبل ما يموتوا دعوا الله إنه يخبر عنهم رسوله،\nفاستجاب الله لهم وأخبر رسوله باللي جرى للصحابة، ورسول الله ﷺ أخبر الناس باللي حصل،\nوحزن رسول الله ﷺ حزن شديد جدا على مقتل أصحابه غدرا،\nوقعد شهر كامل يدعو دعاء القنوت على القبائل إللي غدرت بالصحابة السبعين، \nمتخيلين إنهم نفس عدد قتلى المسلمين في أُحد،\nطيب متخيلين إن رسول الله ﷺ مات من أصحابه حوالي مائة وخمسين في أقل من أربعة أشهر\nالواحد لما بيموت له حد بيحبه سواء صاحب أو قريب بيبقى زعلان وساعات بيبقى مش عارف هيكمل الحياة من غيره إزاي،\nفما بالكم لما يكونوا مائة وخمسين واحد من خيرة أصحابه وأقاربه، وكمان في بداية نشأة الدولة الإسلامية،\nيعني محتاجين القُراء دول عشان يعلموا الناس الدين وينشروا الإسلام، ابتلاء رسول الله ﷺ كان شديد،\nمهما ابتُلينا في فقْد حبيب فمش هنيجي حاجة في ابتلاء رسول الله ﷺ،\nعشان كده ربنا قال لنا: \n\"لَّقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ \"\nكل ما يحصل لنا ابتلاء نشوف رسول الله ﷺ هنلاقي إن ابتلاءه كان أشد فنتصبر ويهون علينا البلاء\n☆وهنا في معلومة، وهي إنه يجوز للمسلم الدعاء على الكفار بصفة عامة، وعلى المحاربين بصفة خاصة زي ما رسول الله ﷺ دعا كده،\nوالدعاء عليهم هو نوع من مدافعتهم والرغبة في زوال الشر وأهله،\nعشان بس لو حد سمع حد بيدعي على الكفار ميقلهوش حرام عليك بتدعي عليهم ليه دول اخواتنا في الإنسانية والكلام العجيب إللي بنسمعه اليومين دول ده\nلاااااكن لا يجوز الدعاء على الكافر المُعين باللعن، يعني محدش ييجي على جاره الغير مسلم ويقول عليه الله يلعنه،\nلأن اللعن ده طرد من رحمة الله،\nواحنا مش عارفين الغير مسلم ده هيُتختم له بإيه،\nممكن ربنا يهديه ويموت على الإسلام\nفالأفضل إنه يدعو له بالهداية، لأن رسول الله ﷺ مكنش بيَعجل بالدعاء على الكفار مادام في أمل إنهم ممكن يدخلوا في الإسلام، بالعكس ده كان بيدعوا لهم بالهداية،\nأما بقى إللي كان كثير الأذى ومفيش منه رجاء وأذاه مستمر ويخاف من ضرره عليه وعلى المسلمين فدول كان رسول الله ﷺ بيدعي عليهم\nنرجع لعمرو بن أمية \nفي طريق عودته للمدينة قابل رجلين من المشركين، وكانا من نفس القبائل إللي شاركت في قتل الصحابة السبعين،\nفظن عمرو بن أمية إنهم شاركوا قومهم في قتل أصحابه فقتلهم انتقاما لأصحابه وأخذ أغراضهم،\nورجع لرسول الله ﷺ في المدينة وأخبره باللي حصل مع الصحابة وأخبره باللي حصل معاه من قتله للرجلين المشركين،\nلكن المشكلة إن الرجلين دول كان راجعين من المدينة وكان معاهم عهد من رسول الله ﷺ ولم يشاركوا في قتل الصحابة،\nفكده هتحصل مشكلة، وزاد حزن رسول الله ﷺ،\nعشان المشركين هيتكلموا إن محمد غدر بالناس إللي أعطاهم العهد\nوصفة الغدر كانت من الصفات القبيحة جدا عند العرب، \nوطبعا انتم عارفين إن محدش هيقول أه عادي حقه ماهو قبيلتهم إللي غدروا الأول،\nولا دول اتقتلوا غلط فمفيش مشكلة نعذرهم\n لأ ده هتلاقيهم بيمسكوا في الخطأ الغير المقصود ويعملوا عليه فرح، ويسيبوا الكوراث إللي هم بيعملوها ولا كأنهم عملوا حاجة\nرسول الله ﷺ عشان ميديش لحد الفرصة إنه يتكلم، ويقفل الباب على أي حد تُسوّل له نفسه إنه يطعن على الإسلام والمسلمين قرر إنه يدفع دِيَة الرجلين،\nاحنا كنا قلنا قبل كده إن معنى الدِّيَة : هو المال إللي بيُعطى لِولِي المقتول بدل نفسه،\nيعني لما الإنسان بيُقتل خطأ يجب على القاتل إنه يدفع مال لأهل المقتول بدل نفسه إللي قُتلت دي،\nفبدأ رسول الله ﷺ يجمع أموال الدية عشان يرسلها لأهل المقتولين، \nوده حقهم يا جماعة لأنهما قُتلا خطأ، فمش معنى إننا كمسلمين حد غدر بينا يبقى احنا كمان نَغدر به،\nاحنا بنتعامل بأخلاق الإسلام إللي بيحرم الغدر بأي حد أُعطي له الأمان ولو كان كافرا\nجمع رسول الله ﷺ مال الدية، لكن لسه المال ناقص واحنا عارفين إن الصحابة فقراء أصلا،\nفهيكمّل الدية إزاي دلوقتي \nالحل إنه يستعين بحلفائه من اليهود، لأن المعاهدة إللي كانت بين اليهود والمسلمين كانت بتقول إن اليهود يدافعوا عن المدينة لو حد هجم عليها، وكمان يساعدوا في دفع الدية عن أي حد يُقتل خطأ،\nاليهود إللي موجودين داخل المدينة دلوقتي هم يهود بني النُّضير، ذهب إليهم رسول الله ﷺ عشان يطلب منهم مساعدته في إكمال الدّية وأخذ معاه أبو بكر وعمر رضي الله عنهما ومجموعة صغيرة من الصحابة،\nلما وصل رسول الله ﷺ لليهود وأخبرهم بالقصة أظهروا له إنهم هيساعدوه وإنهم على العهد وأجلسوه مع أصحابه بجانب بيت من البيوت لحد ما يجمعوا له المال،\nاجتمعوا مع بعض وقالوا:\nمش هتلاقوا فرصة أحسن من دي لقتل محمد \nاتقتل له مائة وخمسين من أصحابه واتهزم في أحد، وهم دلوقتي ضِعاف، وكمان جاي لوحده مع عدد قليل من أصحابه،\nمين فيكم يأخذ هذه الرَّحَى ويطلع على البيت فيرميها على رأس محمد فيكسر رأسه ويقتله وبكده نخلص منه ومن دولة الإسلام كلها مرة واحدة\n☆الرَّحى عبارة عن حجارة مدورة ضخمة بيستخدموها في الطحن، بيطحنوا بيها أي حاجة محتاجة طحن.\nفقال واحد منهم اسمه عمرو بن جَحّاش : أنا هرمي الحجر على رأس محمد\nفقال واحد من زعمائهم اسمه سَلاّم بن مُشْكِم : \nبلاش تعملوا كده، والله ليُخْبَرَنّ بما هَمَمتم به وكده هتنقضوا العهد إللي بيينا وبينه\nيعني هيجيله الوحي يخبره باللي انتم عايزين تعملوه ده،\nلكن حُيَيْ بن أَخْطَب زعيم بني النُّضِير أصر على قتل رسول الله ﷺ،\nفقام عمرو بن جحّاش ومعاه الرّحى وطلع على البيت عشان يرمي الحجر على رأس رسول الله ﷺ ملقهوش\nكان إيه إللي حصل بقى\nفي الوقت إللي هم كانوا عمالين يتفقوا جاء جبريل عليه السلام لرسول الله ﷺ وأخبره بإن بني النُّضير بيدبروا مؤامرة عشان يقتلوه\nفقام رسول الله ﷺ من بين أصحابه من غير ما يقول لهم أي شيء نهائي عشان ميلفتش الأنظار إنه عرف حاجة عن المؤامرة بتاعتهم،\nوإلا كان ممكن اليهود يتجمعوا عليهم وهم عددهم قليل ويقتلوهم، فرسول الله ﷺ بياخد بأسباب السلامة لنفسه ولأصحابه\nالصحابة لما شافوا رسول الله ﷺ قام ومشي راحوا قايمين وراه وفضلوا ماشيين وراه لحد ما وصلوا للمدينة بعيد عن مكان بني النُّضير،\nوهنا أخبرهم بالمؤامرة إللي كان بنو النضير بيدبروها وبإن إللي عملوه ده نقض صريح ومباشر للعهد إللي بينهم وبين المسلمين،\nفقرر رسول الله ﷺ إجلاء بني النّضير من المدينة، يعني يخرجهم من المدينة وميبقاش منهم ولا واحد يعيش في المدينة،\nأرسل لهم رسالة يقول فيها:\n\"اخرجوا من المدينة ولا تساكنوني فيها وقد أجّلتكم عشرا فمن وجدتُه بعد ذلك ضربتُ عنقه\"\nيعني رسول الله ﷺ بيقول لهم اخرجوا برة المدينة متقعدوش معايا فيها، وأنا هديكم مُهلة عشر أيام تجهزوا حالكم وتلموا حاجتكم وتمشوا، وأي حد منكم هلاقيه موجود بعد العشر أيام هقتله\nكان إيه رد فعل اليهود بعد رسالة رسول الله ﷺ، وهل هيسمعوا الكلام من غير مشاكل ولاّ هيركبوا دماغهم ويفضلوا قاعدين في المدينة\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 112, "l": "الجزء 86 | أحداث السنه الرابعه من الهجره | غزوة بني النضير", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة_والثمانون\n#أحداث_السنة_الرابعة_من_الهجرة\n#غزوة_بني_النُّضَيْر\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما أرسل رسالة لبني النُّضير وأمرهم إنهم يخرجوا من المدينة بسبب نقضهم العهد إللي بينهم وبين رسول الله ﷺ،\nلكن قبل ما نعرف هل استجاب بني النُّضَيْر لأمر رسول الله ﷺ ولّا لأ عايز أكمل قصة عامر بن الطفيل إللي اتكلمنا عنه المرة إللي فاتت،\nهو أنا كنت محتار أكمل قصته دلوقتي ولّا استنى لحد ما ييجي وقتها في عام الوُفُود،\nبس على ما ييجي وقتها هتكونوا نسيتم مين هو عامر بن الطفيل أصلا فخليني أكملها لكم دلوقتي أحسن\nعامر بن الطفيل قلنا عنه إنه كان من فَجرة وفُسّاق العرب وكان من بني عامر القبيلة القوية إللي رسول الله ﷺ عرض عليهم الإسلام وهو في مكة قبل الهجرة خالص لو تفتكروا\nوزعيمهم ساعتها قال لرسول الله ﷺ إنهم هينصروه بس المُلك بعد كده يكون لهم ورسول الله ﷺ رفض كلامه وبعدين محصلش الاتفاق وقابل رسول الله ﷺ الأنصار بعدها زي ما حكينا،\nفعامر بن الطفيل كان من القبيلة القوية دي، \nولعله والله أعلم سمع من الزعيم بتاعهم عن اللقاء إللي حصل بين قومه وبين رسول الله ﷺ فبقى عنده حقد على رسول الله ﷺ وعلى المسلمين وانتهز فرصة مَجِيء وفد المسلمين لأرض بني عامر عشان ينتقم منهم،\nحقده ده استمر سنين مع انتصارات المسلمين وتوسّع دولة الإسلام لحد ما جاء عام الوفود بعد فتح مكة سنة تسعة هجريا،\nالعام إللي القبائل كانت بترسل لرسول الله ﷺ وفد من عندها عشان تُعلن إسلامها أو يعملوا معاه عهد صلح أو يأتوا ليعرفوا عن الإسلام،\nقومه قالوا له الناس أسلمت فأسلم انت كمان،\nفقال لهم :\nيعني أنا كنت ببذل جهد عشان العرب تتبعني، فأنا أبقى تابع لفتى من قريش\nفهو لما لقى الوضع بقى بالمنظر ده قرر إنه يغتال رسول الله ﷺ\nفكان له صاحبين على نفس درجة فِسقه وفجوره كده وكانوا شاركوا معاه في قتل السبعين صحابي في بئر معونة واحد اسمه أَرْبَد بن مَقِيس والثاني اسمه جُبَار بن سُلْمى وهو إللي قتل الصحابي حرام بن ملحان وأسلم بعدين واتكلمنا عنه المرة إللي فاتت،\nقال عامر بن الطفيل لصاحبه أربد :\nاحنا نروح لمحمد زينا زي باقي الناس ، وأنا هشغله بالكلام فانت تيجي من وراه وتقتله بالسيف\nفكان ده الاتفاق بينهم، راحوا المدينة عند رسول الله ﷺ وبدأ رسول الله ﷺ يعرض عليهم الإسلام وقال لعامر بن الطفيل: أسلم يا عامر!\n☆مع إن عامر قتل سبعين من الصحابة غدرا بس رسول الله ﷺ عنده استعداد إنه يتغاضى عن كل شيء في مقابل إسلامه،\nيعني هو همه إنقاذ الناس من النار أكثر من الانتقام منهم\nفعامر بن الطفيل قال له: هسلم بشرط إني يكون لي الأمر من بعدك\nيعني عايز إنه يكون الخليفة والحاكم للمسلمين بعد موت رسول الله ﷺ،\nطبعا رسول الله ﷺ رفض كلامه، فقال له عامر بن الطفيل :\nخَالِني يا محمد!\nيعني تعال نتكلم أنا وانت لوحدنا من غير ما يكون حد معانا،\nرسول الله ﷺ قال له:\nلأ، حتى تؤمن بالله وحده لا شريك له\nيعني أنا مش هقعد معاك لوحدنا إلا لما تدخل في الإسلام الأول،\nوعامر عمال يتحايل على رسول الله ﷺ ويشغله ويبص لصاحبه عشان يتحرك ويقتل رسول الله ﷺ زي ما كانوا متفقين وصاحبه واقف مبيتحركش\nكرر الموضوع كذا مرة ويبص لصحابه يعني يلا اخلص واقتله وصاحبه واقف،\nفقال عامر بن الطفيل لرسول الله ﷺ وهو بيهدده:\nوالله لأَمْلأَنّها عليك خيلا ورجالا\nيعني أنا هجيب لك جيش كبير جدا يقضي عليك، \nوأخذ عامر بن الطفيل صاحبه أربد وخرجوا من عند رسول الله ﷺ،\nفدعا عليه رسول الله ﷺ:\nاللهم اكفني عامر بن الطفيل\nبعد ما خرجوا وبِعدوا عن رسول الله ﷺ عامر بن الطفيل مسك أربد وقعد يقول له:\nمعملتش إللي اتفقنا عليه ليه \nبقى أنا إللي كنت بعمل لك حساب لدرجة إني كنت بخاف على نفسي منك، والله ما هخاف منك بعد النهاردة\nفقال له أَربد :\nاصبر بس متستعجلش واعرف إللي حصل\nأنا كنت كل ما أحاول أقتله بالسيف ألاقيك جيت وقفت بيني وبينه، كنت أضربك يعني بالسيف وأقتلك\nفدي معجزة حفظ الله بها رسوله ﷺ من القتل\nفي طريق رجوع عامر وأربد لبلادهم ربنا سلط على عامر بن الطفيل الطاعون في رقبته،\nالطاعون ده زي السرطان في عصرنا كده ربنا يعافينا ويعافي المسلمين،\nواشتد به المرض فجاء الليل فاستضافته امرأة من بني سلول، فهانت عليه نفسه إزاي يموت زي ما البعير بيموت بالغدة في رقبته وكمان يموت في بيت امرأة من بني سلول،\nوبني سلول كانوا من أذل وأجبن قبائل العرب،\nيعني بالنسبة له الموتة دي موتة ذل وهو سيد من سادات العرب وكان يخافه العرب وكمان كان بيناظر كسرى ملك الفرس،وكان الناس بيهابوه ويخافوه،\nفمتوقعش إنه يموت الموتة الذليلة دي، فكان يقول:\nأغُدة كغدة البعير وفي بيت سلولية\nفركب على فرسه عشان يوصل لقومه لكنه مات في الطريق على الكفر\nشوفتم نهاية الكِبر والإعراض عن اتباع الحق وصلته لإيه\nالمفروض يعني إن صاحبه أربد يتعظ بقى ويرجع يستسمح رسول الله ﷺ\nلكن ده معملش كده، لما وصل لقومه سألوه : \nهاه إيه الاخبار، وإيه إللي حصل، عرفتم إيه\nقال لهم أربد بكل اسكتبار وغطرسة:\nمفيش حاجة\nمحمد دعانا لعبادة شيء لو هو عندي قصادي دلوقتي هرميه بالسهام وأقتله \n☆شايفين تكبره وتعديه على إللي خلقه، \nعارفين المتكبر ده وأمثاله من إللي بنشوفهم دلوقتي كان أصلهم إيه؟\nكان أصله من تراب...التراب إللي لو جه على هدوم واحد فيهم بينفضه،\nبكرة هيبقى فوقهم تراب وتحتهم تراب وعن أيمانهم تراب وعن شمائلهم تراب، وهم نفسهم هيتحولوا لتراب في يوم من الأيام كأنهم ما خرجوا من التراب أبدا\nالناس إللي بتتعدى على ربنا وتنكر وجوده وتستكبر عن عبادته لو اجتمع أهل الأرض كلهم بعلمائهم وخبرائهم وأجهزتهم مش هيقدروا يخلقوا لواحد منهم شعرة\nمتخيلين شعرة واحدة بس محدش يقدرها يخلقها،\nمش بنتكلم عن قلب بينبض مائة وخمسة عشر ألف نبضة في اليوم....\nولا بنتكلم عن كِلى تُغَسّل ستة وثلاثين مرة في اليوم،\nولا بنتكلم عن ثلاثمائة وستين مِفصل بيحركوا جسمه...فقط شعرة واحدة...صدق الله :\n\"وَفِي الْأَرْضِ آيَاتٌ لِّلْمُوقِنِينَ ۩ وَفِي أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ \"\nتعتقدوا إن ربنا هيسيب أربد وأمثاله!!! حاشاه سبحانه...إن الله يُمهل ولا يهمل..إن ربك لبالمرصاد...إن الله ليُمْلِي للظالم حتى إذا أخذه لم يُفْلِتْه\nبعد ما أربد قال كلمته دي بيوم أو يومين خرج ومعاه جمل له عشان يبيعه فأرسله الله عليه صاعقة من السماء أحرقته ولم تُبقِ منه شيء\nشوفتم إللي كان بيتبجح ويقول إنه يقدر يقتل ربنا بقى مصيره إيه...يا ترى إحساسه كان إيه وهو بيحترق بالصاعقة...يا ترى إحساسه إيه وهو بيُعذب في قبره لحد دلوقتي إلى قيام الساعة،\nولعذاب الآخرة أشق،\nوالله لو بيصرخ كل يوم وبيعض الأصابع من الندم ويبكي الدم يارب أخرجني وأنا أؤمن بك ومقلش الكلام إللي قلته ده تاني عمره ما يرجع تاني\nأربد خلاص انتهى وملوش فرصة تانية لكن غيره من إللي لسه على قيد الحياة عنده الفرصة للتغيير والإيمان طاعة الله،وإللي يضيع الفرصة دي لا يلُومَنّ إلا نفسه\n\"وَمَا ظَلَمَهُمُ اللَّهُ وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ \"\nتعالوا نشوف الآيات إللي نزلت تعقيبا على مقتل عامر بن الطفيل وأربد بن مقيس ،يقول الله تعالى في سورة الرعد:\n\"اللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ الْأَرْحَامُ وَمَا تَزْدَادُ ۖ وَكُلُّ شَيْءٍ عِندَهُ بِمِقْدَارٍ۩\nعَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ ۩\nسَوَاءٌ مِّنكُم مَّنْ أَسَرَّ الْقَوْلَ وَمَن جَهَرَ بِهِ وَمَنْ هُوَ مُسْتَخْفٍ بِاللَّيْلِ وَسَارِبٌ بِالنَّهَارِ۩\nلَهُ مُعَقِّبَاتٌ مِّن بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ يَحْفَظُونَهُ مِنْ أَمْرِ اللَّهِ ۗ إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ ۗ \nوَإِذَا أَرَادَ اللَّهُ بِقَوْمٍ سُوءًا فَلَا مَرَدَّ لَهُ ۚ وَمَا لَهُم مِّن دُونِهِ مِن وَالٍ۩\nهُوَ الَّذِي يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا وَيُنشِئُ السَّحَابَ الثِّقَالَ۩\nوَيُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلَائِكَةُ مِنْ خِيفَتِهِ وَيُرْسِلُ الصَّوَاعِقَ فَيُصِيبُ بِهَا مَن يَشَاءُ وَهُمْ يُجَادِلُونَ فِي اللَّهِ وَهُوَ شَدِيدُ الْمِحَالِ\"\n☆في هنا فائدة في آية :\n\"لَهُ مُعَقِّبَاتٌ مِّن بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ يَحْفَظُونَهُ مِنْ أَمْرِ اللَّهِ ۗ إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ ۗ \nوَإِذَا أَرَادَ اللَّهُ بِقَوْمٍ سُوءًا فَلَا مَرَدَّ لَهُ ۚ وَمَا لَهُم مِّن دُونِهِ مِن وَالٍ\"\nربنا جعل لكل واحد مننا ملائكة مُوَكلة بحفظه من الجن والإنس والهوام يعني أنواع الحيوانات أو الحشرات المختلفة أو الحوادث أو أي شيء سواء كان الإنسان نايم أو صاحي،\nزي بالضبط كده لما ملوك الدنيا بيكون لهم حرس خاص بيهم يحموهم،\nطول ما الإنسان طائع لله وبيقول الأذكار بتاعة اليوم الملائكة موجودة بتحفظه من أي حاجة تحصل له،\nوقت ما يقصر في الأذكار أو يقع في المعاصي من غير ما يتوب الحماية تترفع،\nفربنا بيقول هنا إن ربنا لا يغير حفظه للناس إلا لو غيروا هم حالهم من الطاعة إلى المعصية،\n\"إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ\"\nوساعات ربنا يُقدّر على الإنسان شيء فالملائكة ترفع حفظها عنه عشان يصيبه قدر الله لحكمة يعلمها الله\nفلما الإنسان يشوف إنه نجى من حادثة...نجى من كارثة نجى من أي حاجة فده بأمر الله للملائكة المسؤولين عن حفظه، \nولو حصل له الابتلاء يبقى بسبب تقصيره في الأصل لأن الملائكة بتكون رفعت حفظها عنه أو إن ربنا له حكمة في ابتلائه فأمر الملائكة إنها ترفع حفظه عن الإنسان\n◇طيب نعرف إزاي الفرق\nالإنسان يشوف حاله:\nلو هو طائع لله بيبعد عن كل نواهيه ويتبع أوامره يبقى هنا ابتلاء لحكمة ربنا يعلمها،\nلو هو مقصر وغرقان في الذنوب والمعاصي يبقى الملائكة هنا رفعت حفظها عنه عشان يُبتلى وربنا يكفر عنه ذنوبه،\nلأن ربنا قال:\n\"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ۩وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ \"\nفمثقال الذر من الذنوب إللي متبناش منها وعملنا حسنات تغطيها هنشوفها في الابتلاءات في حياتنا عشان تعوض نقص الحسنات إللي عندنا\n《هتلاقوا الكلام ده بالتفصيل موجود في محاضرة رائعة جدا للدكتور عبد المحسن الأحمد اسمها حياتك فرصة،》\nنرجع بقى لقصة بني النُّضَير \nاليهود استلموا رسالة رسول الله ﷺ من هنا وألقى الله في قلوبهم الرعب من هنا،\nمع إنهم كانوا أقوياء وعندهم أسحلة كثيرة وأموال وحصون يتحصنوا فيها ضد المسلمين، يعني بالقياسات المادية هم وضعهم أحسن من وضع المسلمين وخصوصا بعد الأزمات الأخيرة إللي تعرض لها المسلمون،\nومع ذلك خافوا وبدأوا يلموا حاجتهم وقرروا يخرجوا من المدينة بدون قتال، والأمور لحد كده ماشية تمااام\nعبد الله بن أبي بن سلول زعيم المنافقين مهنش عليه الأمور تمشي بسلام\nراح لليهود وقال لهم :\nانتم إزاي هتسيبوا أرضكم وبيوتكم وتخرجوا من المدينة،\nادخلوا الحصون بتاعتكم وأنا معايا ألفين مقاتل هيدخلوا معاكم في الحصون ويحاربوا معاكم ويدافعوا عنكم حتى الموت\nشوفوا القرآن بيقول إيه عن الموقف ده في سورة الحشر:\n\"أَلَمْ تَرَ إِلَى الَّذِينَ نَافَقُوا يَقُولُونَ لِإِخْوَانِهِمُ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَاذِبُونَ\"\nبعد ما كان اليهود خلاص خارجين من غير أي مشاكل اقتنعوا بكلام عبد الله بن أبي بن سلول وقالوا مش هنخرج وتحصنوا في حصونهم وأرسلوا لرسول الله ﷺ رسالة:\nاحنا مش هنخرج من ديارنا واعمل إللي تعمله\nوبكده اتفتح على رسول الله ﷺ وعلى المسلمين باب لأزمة جديدة \nلسه مائة وخمسين واحد مقتول، ودي حرب الله أعلم هيموت فيها كم واحد تاني،\nومينفعش إن رسول الله ﷺ يسكت في موقف زي ده وإلا هتبقى هزة كبيرة جدا لسمعة الدولة الإسلامية وهيبان إنها بتضعف أكثر فهيجرّأ القبائل أكثر إنهم يهجموا على المدينة فالكارثة هتبقى أكبر\nفكان لازم القرار الحازم بحفظ كرامة وسُمعة الدولة الإسلامية، فقرر رسول الله ﷺ بإنه يحاصر بني النضير عشان يخرجهم من المدينة بالقوة\n \nفي شهر ربيع الأول من السنة الرابعة من الهجرة جهز رسول الله ﷺ جيش وانطلق لحصار بني النُّضير،\nوحاصرهم من كل مكان على الراجح ست ليالي وبعد كده اليهود خافوا ومستحملوش وراحوا مستسلمين لأمر رسول الله ﷺ \nمع إن اليهود كان ممكن يعيشوا داخل حصونهم دي سنين لأن عندهم كل حاجة...الأكل والماء والسلاح،\nلكنهم انهزموا بالرعب إللي ربنا أرسله على قلوبهم\n\"لَأَنتُمْ أَشَدُّ رَهْبَةً فِي صُدُورِهِم مِّنَ اللَّهِ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ \"\n☆عشان نتعلم بس يا جماعة إن في حاجة اسمها التوكل والاعتماد على الله،\nهي قلوب البشر دي بين إيدين مين، مش بين إيدين ربنا وهو  قادر إنه يغيرها في لحظة،\nهو حد يقدر يضر وينفع حد إلا بأمر الله وإذنه،\nرسول الله ﷺ أخذ بالأسباب وجهز الجيش وخرج، \nعمل إللي عليه وخلاص وهو كان متوقع إن هيبقى في حرب لأنه لا يعلم الغيب إلا إللي ربنا يقول له عليه عن طريق الوحي،\nومع ذلك ربنا كفاه هو والمسلمين إللي معاه الحرب وخلى اليهود يستسلموا بقدرته سبحانه،\n\"وَلَٰكِنَّ اللَّهَ يُسَلِّطُ رُسُلَهُ عَلَىٰ مَن يَشَاءُ \"\nلازم نتعلم من الموقف ده إن الإنسان يعمل إللي عليه حتى ولو قدراته ضعيفة، ميخليش الشيطان يحط له عقبات وهمية من غير حتى ما ياخد خطوة عشان يشوف بيها هل العقبات دي حقيقة ولّا لأ،\nكم مرة حصل معانا موقف وكنا متوقعين أسوأ النتائج وكنا خايفين وبمجرد ما أخذنا القرار ونفذناه لقينا إن كل إللي كنا خايفين منه كان مجرد سراب وإن ربنا يسر لنا أمورنا\nخليكم فاكرين طاعة ربنا والتوكل عليه لا تأتي إلا بخير، البشر دول مجرد آلات لا يملكون إلا إنهم ينفذوا أمر ربنا،\nفإذا لجأنا إلى الله يبقى كل حاجة هتتحل،\nلكن احنا مشكلتنا إننا دايما بنبص للناس على إنهم هم إللي في إيدهم يضرونا أو ينفعونا وبالتالي نخاف منهم ونعمل لهم حساب وناسيين قول رسول الله ﷺ:\n\"وَاعْلَمْ أَنَّ الْأُمَّةَ لَوْ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ لَمْ يَنْفَعُوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَكَ وَلَوْ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ لَمْ يَضُرُّوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ عَلَيْكَ\"\nاستسلم اليهود لرسول الله ﷺ يحكم فيهم زي ماهو عايز وعبد الله بن أبي بن سلول رأس المنافقين انسحب وهرب ولم يقاتل معهم زي ما وعدهم ولم ينفعهم بشيء وصدق الله\n\"لَئِنْ أُخْرِجُوا لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ الْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ \"\nأمرهم رسول الله ﷺ إنهم يخرجوا من المدينة معاهم ممتلكاتهم فقط ومياخدوش السلاح،\nفبقوا يحملوا كل إللي يقدروا يحملوه على الجمال، لدرجة إنهم خرّبوا بيوتهم وبقوا يخلعوا الأبواب والشبابيك عشان يأخذوها معهم\n\"هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ مِن دِيَارِهِمْ لِأَوَّلِ الْحَشْرِ ۚ مَا ظَنَنتُمْ أَن يَخْرُجُوا ۖ \nوَظَنُّوا أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ اللَّهِ فَأَتَاهُمُ اللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا ۖ وَقَذَفَ فِي قُلُوبِهِمُ الرُّعْبَ ۚ \nيُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِي الْمُؤْمِنِينَ فَاعْتَبِرُوا يَا أُولِي الْأَبْصَارِ\"\nتركت بنو النضير المدينة ولم يسلم منهم إلا رجلان، أما زعماء بني النضير حُيَيْ بن أخطب و《أبو رافع سَلاّم بن أبي الحُقَيْق》توجهوا لشمال المدينة لمنطقة اسمها حصون خيبر،\n☆خليكم فاكرين اسم أبو رافع ده، له قصة بعدين\nوبكده انتهت أزمة بني النضير بكل سهولة ويسر، وغَنِم المسلمون السلاح والثمار، وانتشر الخبر في الجزيرة العربية إزاي المسلمون استطاعوا إنهم ينتصروا على قبيلة بني النضير إللي لها تاريخ طويل في المدينة ولها تاريخ في صنع السلاح والقلاع والحصون بكل سهولة،\nوبكده يكون المسلمون استعادوا جزء كبير من هيبتهم\nطبعا رسول الله ﷺ استغل الحدث ده عشان يثبت أقدام الدولة الإسلامية من جديد وسط الجزيرة العربية فجهز جيش عشان يروح يقاتل قبائل نجد إللي قتلوا أصحابه السبعين ، وخرج هو ﷺ على رأس الجيش في غزوة اسمها غزوة نجد، \nلكن المشركين هربوا منه ومحدش خرج لقتاله وانتشر الخبر في جزيرة العرب وبكده زادت هيبة المسلمين في نظر أعدائهم، ورجع رسول الله ﷺ إلى المدينة.\n☆السؤال بقى...هو ليه رسول الله ﷺ لم يُعاقب عبد الله بن أبي بن سلول والمنافقين معاه على معاونتهم لليهود\nوربنا قال عنهم :\n\"أَلَمْ تَرَ إِلَى الَّذِينَ نَافَقُوا يَقُولُونَ لِإِخْوَانِهِمُ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَاذِبُونَ\"\nاحنا اتكلمنا في الجزء الرابع والستين عن المنافقين بصفة عامة وبتوضيح كبير عن كل حاجة تخصهم،\nفأنا هذكّركم هنا بسبب واحد بس \nقلنا إن عبد الله بن أبي بن سلول ظاهره الإسلام فلو رسول الله ﷺ قتله هينتشر في جزيرة العرب إن محمد يقتل أصحابه، فكده الناس هتخاف تدخل في الإسلام،\nفرسول الله ﷺ استحمل الضرر إللي الجاي من المنافقين وعلى رأسهم عبد الله بن أبي بن سلول في مقابل مصلحة أكبر وهي دخول الناس في الإسلام بدون أي خوف\nدلوقتي دخلنا في شهر ربيع الثاني، وفي وسط فرح المسلمين باستعادة هيبة الدولة الإسلامية وبدأوا يقفوا على رجلهم تاني ماتت زينب بنت خزيمة زوجة رسول الله ﷺ وهي لسه عندها ثلاثين سنة ويادوب لسه مكملتش ثمانية أشهر زواج من رسول الله ﷺ \nاحنا كنا قلنا إن رسول الله ﷺ  تزوجها في شهر رمضان\nمن السنة الثالثة من الهجرة بعد موت زوجها عُبيدة بن الحارث،\nوكان رسول الله ﷺ تزوجها مواساة لها بعد موت زوجها، وكانت امرأة تقية تساعد المحتاجين لدرجة إن كان لقبها أم المساكين،\nفماتت أم المساكين، وكانت هي ثاني زوجة تموت لرسول الله ﷺ بعد خديجة رضي الله عنها،\nفلم يمت من زوجات رسول الله ﷺ في حياته غير خديجة وزينب بنت خزيمة رضي الله عنهما،\nوأصبح عدد زوجات رسول الله ﷺ ثلاثة بعد موت زينب ودفنها رسول الله ﷺ في البَقِيع وهو مكان دفن من يموت من المسلمين،\nفي وسط الأحداث دي كلها، في مكة كان أبو سفيان بن حرب رئيس مكة بيسأل مجموعة من قريش :\nمفيش واحد يروح يتسلل ويقتل لنا محمد، هو بيمشي في الأسواق لوحده ومش معاه حراسة فهتكون مهمة سهلة\nفقال له رجل من الأعراب......\nقال له إيه \nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 113, "l": "الجزء 87 | حادثة السنه الرابعه من الهجره | سرية عمرو بن اميه الضمري", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السابعة_والثمانون\n#أحداث_السنة_الرابعة_من_الهجرة\n#سرية_عمرو_بن_أمية_الضِّمْرِي\nكنا واقفين المرة إللي فاتت عند أبو سُفيان لما كان بيدبر خطة لاغتيال رسول الله ﷺ وسأل مجموعة من قريش مين يقدر يروح يقتل محمد ويرجع،\nفواحد من الأعراب قال له بينه وبينه عشان محدش يعرف والخبر يوصل لرسول الله ﷺ:\nانت لقيت أشجع الرجال وأقواهم وأسرعهم في الهرب من الأعداء=بيتكلم عنه نفسه= فلو انت كفَيْتني هروح لمحمد في المدينة وأقتله، وأنا معايا خنجر زي ريشة النسر الصغيرة محدش هياخد باله من الخنجر ده،\n《خنجر يعني حاجة زي السكينة كده》\nوهقرب منه وأقتله وأطلع على البعير بسرعة وأهرب قبل ما حد يلحقني وأنا أصلا حافظ الطريق فمحدش هيقدر يمسكني\nيعني الأعرابي بيطلب من أبي سفيان إنه يجهز له بعير يسافر عليه ومعاه أموال وأكل في مقابل إنه يروح يقتل رسول الله ﷺ، ووضّح له إزاي هيقتل رسول الله ﷺ عشان أبو سفيان يبقى مطمئن ويوافق على عرض الأعرابي،\nفعلا أبو سفيان عجبته الفكرة وقال له: انت صاحب المهمة دي\n وجهزه أبو سفيان باللي هو طلبه وأكّد عليه إنه ميقلش لحد والموضوع يبقى سر بينهم\nانطلق الرجل في اتجاه المدينة بسرعة غير معتادة ، يعني المسافة إللي الناس بيقطعوها في يومين كان بيقطعها هو في يوم واحد ودي كانت عادة الأعراب الأقوياء،\nومقلش لأي حد عن مهمته ولا عن الحوار إللي كان بينه وبين أبو سفيان،\nلما وصل المدينة سأل عن رسول الله ﷺ، وطبعا لأن الصحابة متعودين إن ناس كتير بتيجي تسأل عن رسول الله ﷺ عشان يسألوه عن الإسلام فاعتقدوا إن الأعرابي ده هو كمان جاي يتعلم عن الإسلام فدلُّوه على مكانه ﷺ وقالوا له إنه في مسجد وَاقِم مسجد بني عبد الأَشْهَل،\n☆بني عبد الأشهل دول هم قوم سعد بن معاذ سيد الأَوس إللي دعاه مصعب بن عمير للإسلام وهو راح دعا قومه للإسلام وأسلموا كلهم معاه في نفس اليوم، \nواتكلمنا عن قصة إسلامهم في الجزء الثاني والأربعين لو تفتكروا\nالمهم الأعرابي توجه لمسجد بني عبد الأشهل فلقى رسول الله ﷺ قاعد مع مجموعة من أصحابه، فلما رآه رسول الله ﷺ وهو داخل عليه قال لأصحابه:\nالرجل ده يريد الغدر والله حائل بينه وبين ما يريد\n☆فاكرين لما قلنا من أَسرّ سريرة ألبسه الله رداءها علانية، \nإنْ خيرا فخير وإن شرّا فشر،\nأهه الرجل ده ربنا أظهر على وجهه إللي كان مخبيه في قلبه،\nورسول الله ﷺ بيقول :\n\"إن لله عبادا يَعرفون الناس بالتّوَسُّم\"\n《حديث حسن صحيح》\nيعني المؤمن ممكن لو شاف إنسان يعرف هو مخبي إيه من غير ما حد يقول له أي حاجة، بتبقى رؤية قلبية، يعني بيشوف بقلبه ودي اسمها البصيرة أو الفِراسة،\nربنا بيقول :\n\"فَإِنَّهَا لَا تَعْمَى الْأَبْصَارُ وَلَٰكِن تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ\"\n ودي مش لأي حد، هي للي بيلتزم بالعبادات والطاعات وميعملش الكبائر سواء إللي لها عقوبة في الدنيا\n《 لها حد يعني》زي الزنا والسرقة وغيرها ،\nأو إللي ملهاش عقوبة في الدنيا 《يعني ملهاش حد》زي الغيبة والنميمة والكذب والحقد والحسد وغيرها،\nوكمان لا يُصِر على فعل ذنب صغير يعني لو عمل ذنب يتوب ويستغفر ويعمل أعمال صالحة وكمان ياخد باله إنه لا يأكل إلا الحلال الطيب\nودول اسمهم المتوسّمين إللي ربنا ذكرهم في القرآن:\n\"إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّلْمُتَوَسِّمِينَ \"\nوفي حديث تاني برده عن الفِراسة العلماء اختلفوا فيه، في علماء قالوا إنه ضعيف وعلماء قالوا إنه حديث حسن،\nبس هو معناه صحيح ويشهد له الواقع بكده،\nالحديث هو:\n\"اتقوا فِراسة المؤمن فإنه يَنظر بنورِ الله\" \nالكلام ده كله\n للمؤمن العادي فما بالكم برسول الله ﷺ المُؤيد بالوحي، وإللي كان بيشوف إللي الناس مش بتشوفه،\nزي ما شاف موسى عليه السلام وهو يصلي في قبره في رحلة الإسراء والمعراج،\nوزي ما كان بيشوف الصحابة من ظهره من غير ما يلتفِت ويبص عليهم،\nفكان طبيعي جدا إن لما رسول الله ﷺ يشوف الأعرابي داخل عليه يعرف إنه وراه الغدر\nالأعرابي دخل على رسول الله ﷺ وهو ميعرفوش، فسأل الناس إللي قاعدة:\nمين فيكم ابن عبد المطلب\n☆وهنا في عِبرة جميلة جدا وهي إن رسول الله ﷺ كان زيه زي الصحابة، لبسه زي لبسهم، لما بيقعد معاهم كان بيقعد في وسطهم،\nمش إنه كان بيقعد على كرسي مُلك وهمّ قاعدين في الأرض، مكنش بيميز نفسه عنهم إطلاقا،\nودي من أهم صفات القائد الناجح إنه يذوب في وسط أتباعه، \nمع إن رسول الله ﷺ لو ميّز نفسه عن الصحابة مكنوش هيعترضوا بالعكس، \nده همّ نفسهم يميّزوه ويُعطوا له المكانة العظيمة من حبهم له لكنه ﷺ كان متواضع جدا مكنش بيرضى بأي نوع من أنواع التعظيم والتمييز له،\nلدرجة إن إللي بيدخل عليه وميعرفش شكله مش بيبقى عارف هو أنهو واحد من الناس إللي قاعدة\nالأعرابي لما سأل من فيكم ابن عبد المطلب، قال له رسول الله ﷺ: \nأنا ابن عبد المطلب!\nفالأعرابي توجه لرسول الله ﷺ كأنه هيقول له حاجة في أذنه، فراح أُسيد بن حُضَيْر شدّه من هدومه فجأة وقال له:\nابعد عن رسول الله ﷺ \nفلقوه مخبي الخنجر في إيده \nالأعرابي كده اتكشف خلاص، وهو عارف إن محاولة اغتيال أي زعيم نهايتها القتل، فاترعب وقعد يقول :\nدمِي، دمِي\nيعني محدش يقتلني، فرسول الله ﷺ قال له :\nقول لي الحقيقة، انت مين وإيه إللي جابك عندنا هنا، ولو كذبت عليّ، فأنا عارف أصلا انت جيت ليه\nفالأعرابي قال لرسول الله ﷺ: وأنا آمن\n \nيعني لو قلت لك الحقيقة مش هتقتلني،\nفرسول الله ﷺ طمّنه وقال له: نعم، وأنت آمِن\nفالأعرابي حكى له الحكاية كووولها، فأمر رسول الله ﷺ أسيد بن حضير إنه يحبسه عنده،\nتاني يوم الصبح أمر رسول الله ﷺ أسيد بن حضير إنه يأتي له بالأعرابي، فلما جاءه بالأعرابي قال له رسول الله ﷺ:\nأنا أعطيتك الأمان، فاذهب حيث شئت!...أو أقول لك على حاجة أحسن من كده\nفالأعرابي سأل باهتمام: وإيه هو الأحسن\nقال له رسول الله ﷺ:\nتشهد ألا إله إلا الله وأني رسول الله\nفقال الأعرابي:\nأشهد ألا إله إلا الله وأنك رسول الله \nوالله يا محمد أنا عمري ما خفت من أي حد، لكن أول ما شفتك ضعفت وخُفت، وانت كمان عرفت إللي أنا كنت ناوي عليه، ومحدش عرف الموضوع ده غيري أنا وأبو سفيان،\nفعرفت إنك ممنوع ومحدش يقدر يقرب لك وإنك على حق\nفكان رسول الله ﷺ بيتبسم وهو بيسمع كلام الأعرابي\nقعد الأعرابي كم يوم في المدينة يتعلم الإسلام واستأذن رسول الله ﷺ بعدها ومشي،\nومحدش يعرف حصل له إيه بعد كده، وحتى محدش يعرف اسمه إيه.\nكده الوضع بقى خطير، فلازم يكون في رد على محاولة الاغتيال دي عشان الناس تعرف قوة المسلمين\nرسول الله ﷺ اختار رجل من المحاربين الأشداء والفدائيين النوادر عشان يقوم بمهمة اغتيال الرجل إللي حاول اغتياله ﷺ: أبو سفيان سيد مكة\nالرجل القوي ده كان عمرو بن أمية الضِّمري الناجي الوحيد تقريبا من حادثة بئر معونة، وجعل رسول الله ﷺ معاه واحد من الأنصار،\nقال لهما رسول الله ﷺ: \nاخرجا حتى تأتيا أبا سفيان بمكة، فأول ما تلاقوه لوحده اقتلوه\nخرج الرجلان على الجملين بتوعهم وتوجهوا لمكة عشان ينفذوا أمر رسول الله ﷺ، \nوصلوا لمكان قبل مكة بحوالي اثنا عشر كيلو متر وربطوا الجملين وقعدوا وكان الليل دخل، فقال الأنصاري لعمرو بن أمية:\nإيه رأيك ندخل مكة ونطوف بالبيت ونصلي ركعتين\nفقال له عمرو بن أمية:\nأنا أعرف بأهل مكة منك، لما الليل بييجي بيرشوا قصاد بيوتهم ويقعدوا،\nوأنا أشهر عند أهل من مكة من الفرس الأبلق\nيعني بمعنى أصح أهل مكة كلهم صاحيين دلوقتي وكلهم عارفين عمرو بن أمية كويس فلو شافوه هيعرفوه وهتبقى كارثة\nفالأنصاري قعد يِلح على عمرو بن أمية فوافق عمرو وتسللوا ودخلوا مكة وطافوا بالكعبة وصلوا ركعتين وخرجوا يبحثوا عن أبي سفيان،\nهم خارجين من هنا إلا ومعاوية بن أبي سفيان في وشهم\nفعرفه معاوية بن أبي سفيان على طول وقال:\nعمرو بن أمية، واحزناه\nيعني زي ما بنقول بالبلدي كده: يادي الهم\nصاح معاوية بأهل مكة إن عمرو بن أمية موجود في مكة،\nطبعا عمرو بن أمية وصاحبه الأنصاري هربوا للجبل،\nتجمع أهل مكة وبدأوا يتكلموا عن عمرو:\nقالوا والله ما جاء عمرو في خير، أكيد جاي يعمل مصيبة\nوهم كانوا عارفين إن عمرو بن أمية من الأشداء الأقوياء من أيام الجاهلية،\nفبدأو يدوّروا على عمرو وصاحبه خصوصا في الجبل، وكان ساعتها عمرو بن امية وصاحبه الأنصاري دخلوا في غار في الجبل وفضلوا قاعدين فيه لحد تاني يوم،\nومحدش من المشركين فكر إنه يبحث عنهم في طريق المدينة، وده كان من حفظ الله لهما؛\nلأنهم لو كانوا اتجهوا لطريق المدينة كانوا هيلاقوا الجملين بتوعهم وكانت هتبقى ورطة\nتاني يوم على الضحى كده جاء واحد من المشركين بيرعى لفرسه، يعني بيبحث لفرسه عن زرع أخضر في الجبل،\nفعمرو بن أمية قال لصاحبه:\nالرجل ده لو شافنا هيروح يقول لأهل مكة عن مكاننا واحنا ما صدقنا إنهم خلاص رجعوا وتركونا\nفالمشرك قعد يقرب من الغار ويقرب ..ويقرب..لحد ما خلاص كان هيشوفهم\nفخرج له عمرو بن أمية وانقض عليه وطعنه تحت صدره، فسقط على الأرض وصرخ بالناس؛ فلأن الصراخ في الجبل بيعمل صدى صوت عالي جدا الناس سمعوا صوته وجاؤوا له،\nوكان عمرو بن أمية رجع لمكانه في الغار يستخبى،\nفلما جاء الناس لقوا الرجل المشرك في النفس الأخير، فسألوه: مين قتلك\nفقال لهم : عمرو بن أمية! ومات الرجل وملحقش يقول لهم هم مستخبيين فين،\nفقال أبو سفيان وكان معاهم:\nاحنا قلنا إن عمرو بن أمية مجاش لخير\nفأخذوا الرجل القتيل وانشغلوا به عن البحث عن عمرو بن أمية،\nجلس عمرو بن أمية مع صاحبه الأنصاري في الغار يومين لحد ما الدنيا هديت خالص وبعدين خرجوا من الغار عشان يرجعوا للمدينة،\nوصلوا لمنطقة اسمها التنعيم وهي منطقة برة الحرم المكي إللي المشركين صلبوا فيها خبيب بن عدي رضي الله عنه وقتلوه،\nفالأنصاري قال لعمرو بن أمية:\nإيه رأيك نروح لخُبيب وننزله من على خشبة الصلب\nفقال له عمرو: وهو فين خبيب\nفقال له : أهه هناك مصلوب وحوله الحرس\nفقال له عمرو:\nاستنى شوية، وخليك انت بعيد، لو حسيت إن في مشكلة وخُفت على نفسك اركب جملك واسبقني على المدينة واحكي لرسول الله ﷺ إللي حصل، ومتشغلش نفسك بي، أنا حافظ طريق المدينة\nراح عمرو بن أمية ناحية جثة خُبيب المصلوبة والحرس نايمين قريب منه،\nالحرس دول كان مهمتهم إنهم يحرسوا جثة خبيب عشان محدش من المسلمين يأتي ويأخذها،\nاستطاع عمرو بن أمية إنه ينزل جثة خبيب وحملها على ظهره ومشي به،\nيادوب مشي بيه خمسة عشر متر ولقى الحراس جايين وراه\nفوضع جثة خُبيب على الأرض وبدأ يحط التراب عليه برجله،\nوفي رواية تانية بتقول إن عمرو بن أمية أول ما أنزل جثة خبيب من على خشبة الصلب ووضعها على الأرض والْتفت عنها لحظات وبيبص تاني عليها ملقهاش، وعرف إن الأرض بلعتها\nالمهم إن جثته نزلت من على الخشبة ودُفن في الأرض رضي الله عنه\nالأنصاري كان ركب الجمل بتاعه وانطلق نحو المدينة، \nوصل عمرو بن أمية لجمله وأخذه ومشي في اتجاه المدينة،\nوهو ماشي تعب فدخل في كهف صغير أو غار يريح شوية، وهو قاعد دخل عليه شيخ كبير أعور ومعاه أغنام له،\nفسأل عمرو بن أمية : إنت مين\nفقال له عمرو: أنا رجل من بني بكر\nفقال الرجل: وأنا من بني بكر\n《بني بكر من قريش》\nوبعدين الرجل اتكأ على الأرض وقعد يقول:\nولستُ بمسلمٍ ما دمتُ حيّا ** ولستُ أدينُ دينَ المسلمينَا\nيعني أنا مش هدخل الإسلام أبدا\nفخاف عمرو إن الرجل ده يقول لحد على مكانه، فصبر لحد ما نام وبعدين قتله عمرو، وخرج من الغار وكمل طريقه،\nالمسافة من مكة للمدينة خمسمائة كيلو، فمسافة مش بسيطة خالص واخدها مشي\nلما كان خلاص قرّب من المدينة قابل رجلين من قريش كانوا جايين يتجسسوا ويعرفوا الأخبار من حول المدينة،\nلأن كمان كم شهر في ميعاد حرب بين رسول الله ﷺ وبين المشركين في بدر متفقين عليها من بعد أحداث أُحد،\nفهم بيتجسسوا على رسول الله ﷺ،\nلما شافهم عمرو قال لهم:\nاستسلما لي\nفرفضوا، فرمى عمرو واحد منهم بسهم فقتله ،فالتاني لما شاف إللي حصل لصاحبه استسلم لعمرو،\nفقيّده عمرو، كتّفه يعني وأخذه لرسول الله ﷺ، دخل عمرو ومعاه الأسير للمدينة وكان صبيان الأنصار بيلعبوا،\nفشافه الناس وقالوا : ده عمرو جه\nوطبعا كانوا عرفوا إللي حصل لأن صاحبه الأنصاري كان وصل قبله بثلاثة أيام،\nالصبيان لما سمعوا الناس بتقول جاء عمرو، انطلقوا لرسول الله ﷺ عشان يقولوا له على خبر مجيء عمرو\nدخل عمرو ومعاه الأسير على رسول الله ﷺ فرآه يضحك له ودعا له بخير\nدخلنا في شهر جمادى الأولى من السنة الرابعة من الهجرة، وفي الشهر ده مات ابن عمة رسول الله ﷺ وأخوه وأخو حمزة بن عبد المطلب من الرضاعة عبد الله بن عبد الأسد المخزومي، المشهور بكنيته أبو سَلَمة،\nأبو سلمة كان من أوائل الناس إللي أسلمت وكان من كبار الصحابة، \nكان أسلم على يد أبو بكر الصديق لو تفتكروا، وكان من المهاجرين الأوائل للحبشة ومن المهاجرين الأوائل للمدينة بعد كده،\nوكان متزوج من أم سَلمة وحكينا قصتهم في الجزء الرابع والأربعين، وسبب موته إنه كان أصيب بجرح شديد في غزوة أحد، فالجرح فتح تاني ومبقاش له علاج، فلما حضرت أبو سلمة الوفاة دعا وقال:\nاللهم اخلفني في أهلي بخير\nومات رضي الله عنه وشَخُصَ بصره للسماء وكان رسول الله ﷺ حاضر في الوقت ده فأغمض له عينه وقال :\n\"إن الرّوح إذا قُبِض تبِعه البصر\"\nيعني الإنسان بيفضل باصص على روحه وهي طالعة للسماء،\nعشان كده لما الميت بيموت عينه بتكون مفتوحة فالسنة هنا إننا نُغمِض للميت عينه،\nلما الناس في البيت عرفوا إن أبو سلمة مات بدأوا يبكوا ويعملوا صوت وبدأ يبقى في ضجة،\nفرسول الله ﷺ لحقهم وقال لهم:\nلا تدعوا على أنفسكم إلا بخير، فإن الملائكة يُؤَمّنُون\nثم قال:\nاللهم اغفر لأبي سلمة وارفع درجته في المَهْديِين واغفر لنا وله يارب العالمين\nوغسّلوه وكفنوه وصلى عليه رسول الله ﷺ  ودفنوه في البقيع رضي الله عنه وأرضاه.\n☆رسول الله ﷺ مقلهمش محدش يعيط ولا قال لهم محدش يحزن، دي طبيعة مشاعر البشر، وكان رسول الله ﷺ بيراعي مشاعر الناس جدا ، وكان دايما بيوجهها بحيث إنها  تكون مُقيدة بالشرع،\nالحزن مش مُبرر أبدا لمعصية الله، عايز تحزن احزن لكن في حدود الشرع، يعني عايز تعيط عيط من غير صويت ونياحة،\nحصلت لك مشكلة والموضوع مأثر على نفسيتك مفيش مشكلة، لكن متدعيش على نفسك\nطبعا أنا مش هقول لكم على مشاعر أم سلمة كانت عاملة إزاي في الوقت ده\nامرأة عاشت مع زوجها قصة كفاح طويلة حوالي سبعة عشر عام من بداية الإسلام، وكانت بتحبه وهو أبو أبنائها،\nمهما حاولنا نوصف مشاعرها مش هنعرف، لكنها في الموقف ده وعلى الرغم من إللي هي كانت فيه تذكرت كلام رسول الله ﷺ إللي كان قاله قبل كده عن المسلم إللي تصيبه مصيبة يعمل إيه\nقالت:\nإنا لله وإنا إليه راجعون، اللهم أجرني في مصيبتي واخلف لي خيرا منها\nلكنها قالت في نفسها: وهو في أحد في المسلمين خير من أبي سلمة\n☆ بيحصل معانا مواقف مشابهة، لما بنفقد شيء أو شخص عزيز ونقول الدعاء ده بيقع في نفسنا وهو في أحسن من فلان،\nأو هو في أحسن من إللي ضاع مني، واحنا منعرفش إن ربنا هيرزقنا بالأحسن لأن ده وعد من رسول الله ﷺ،\nزي أم سلمة رضي الله عنها، هي قالت الدعاء زي ما رسول الله ﷺ قال للمسلمين بصفة عامة،\nوهي متعرفش إن بعد كم شهر بس ربنا هيرزقها مش بمن هو خير من أبي سلمة ده ربنا هيرزقها بخير مَن وطأت قدمه الأرض من البشر\nاوعوا تنسوا وعد رسول الله ﷺ \n\"ما من مسلم تصيبه مصيبة فيقول:\nإنا لله وإنا إليه راجعون ، اللهم أجرني في مصيبتي وأخلف لي خيراً منها، إلا أخلف الله له خيراً منها\nيا ترى حصل إيه تاني بعد كده ده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
